import { useQuery } from "@tanstack/react-query";

export const useSecretKey = () => {
    const {
        data: secretKey,
        isLoading,
        isFetched,
    } = useQuery({
        queryKey: ['user-key'],
        queryFn: ({ signal }) =>
            fetch('/api/user/key', {
                method: 'PUT',
                signal: signal,
            })
                .then(response => response.json())
                .then(response => response.key),
        gcTime: 1000 * 60 * 60 * 24,
    });

    return {
        secretKey,
        isLoading,
        isFetched,
    }
};