import type { Build } from '@gsm-app/models/Build';
import { BuildState } from '@gsm-app/models/BuildState';
import { useMemo } from 'react';

export const useBuildStateProps = (build: Build | null | undefined) => {
    const buildState: BuildState | string | undefined = build?.state;
    return useMemo(() => {
        if (buildState) {
            if (
                buildState !== BuildState.INSTALL_FAILED &&
                buildState !== BuildState.INSTALL_IN_PROGRESS &&
                buildState !== BuildState.INSTALL_SUCCEED
            ) {
                return {
                    value: 'Cannot play the build. Please upload a new build.',
                    color: 'red',
                    playable: false,
                };
            } else {
                if (buildState === BuildState.INSTALL_FAILED) {
                    return {
                        value: 'Install unsuccessful',
                        color: 'red',
                        playable: false,
                    };
                } else if (buildState === BuildState.INSTALL_IN_PROGRESS) {
                    return {
                        value: 'Install in progress',
                        color: 'yellow',
                        playable: false,
                    };
                } else {
                    return {
                        value: 'Active',
                        color: 'green',
                        playable: true,
                    };
                }
            }
        }
        return {
            value: undefined,
            playable: false,
        };
    }, [buildState]);
};
