import { GameVisibility } from '@netflix-internal/nf-game-control-protocol';
import { useCallback, useEffect, useRef, useState } from 'react';
import type { BrowserGamingClient, Env, PlayerMetricEvent, PublicEventsMap } from '../api/BrowserGamingClient';
import { type LogEntry, LogLevel } from '../api/common/Logger';
import { StartGameError } from '../api/controlplane/ControlPlane';
import type { LoadingStep } from '../api/utils/LoadingProgressReporter';

export type OCGAStatsSample = {
    timestamp?: number;
    sessions?: Record<string, string | number | undefined>;
    metrics?: Record<string, string | number | undefined>;
};

export type OCGAOverrides = {
    ocgas?: string[];
    gameEnvs?: Env[];
    hardwareVersionSelection?: string; // Format: "hardwareName:environment"
    softwareGameDevPool?: string;
    resolutionOverride?: number;
    fpsOverride?: number;
};

export type LogForwardingOptions = {
    minLevel?: LogLevel;
    includedTopics?: string[];
    excludedTopics?: string[];
};

export type LoadingProgress = {
    step: LoadingStep;
    stepLabel: string;
    progress: number;
    gameLoadPercent: number;
};

export function useGamingClientMonitor(
    shouldInitialize: boolean,
    gamingClient: BrowserGamingClient,
    options: {
        signalingServer?: string;
        sopAccountEmail: string;
        sopAccountPin: string;
        resolutionOverride?: number;
        fpsOverride?: number;
        buildId: string;
        controllerEnv?: string;
        testbedVersion?: string;
        ocgaOverrides?: OCGAOverrides;
        onError?: (e: Error) => void;
        onLog?: (logEntry: LogEntry) => void;
        onMetric?: (metric: PlayerMetricEvent) => void;
        logForwardingOptions?: LogForwardingOptions;
    },
) {
    const [sdpDebug, setSpdDebug] = useState<Record<RTCSdpType, RTCSessionDescriptionInit>>(
        {} as Record<RTCSdpType, RTCSessionDescriptionInit>,
    );
    const [loadingProgress, setLoadingProgress] = useState<LoadingProgress>({
        step: 'connecting',
        stepLabel: 'Connecting to server',
        progress: 0,
        gameLoadPercent: 0,
    });

    const onLogRef = useRef(options.onLog);
    const onErrorRef = useRef(options.onError);
    const onMetricRef = useRef(options.onMetric);
    const logForwardingOptionsRef = useRef(options.logForwardingOptions);

    useEffect(() => {
        onLogRef.current = options.onLog;
        onErrorRef.current = options.onError;
        onMetricRef.current = options.onMetric;
        logForwardingOptionsRef.current = options.logForwardingOptions;
    }, [options.onLog, options.onError, options.onMetric, options.logForwardingOptions]);

    const handleLog = useCallback(({ logEntry }: PublicEventsMap['log']) => {
        // Handle SDP debug info
        if (logEntry.topic === 'SDP') {
            const message = logEntry.messageItems[0];
            setSpdDebug((prev) => ({ ...prev, [message.type]: message }));
        }

        // Forward logs to external system if callback is provided
        const onLog = onLogRef.current;
        if (!onLog) return;

        const forwardOpts = logForwardingOptionsRef.current ?? {};
        const minLevel = forwardOpts.minLevel ?? LogLevel.INFO;

        if (logEntry.level < minLevel) return;
        if (forwardOpts.includedTopics && !forwardOpts.includedTopics.includes(logEntry.topic)) return;
        if (forwardOpts.excludedTopics?.includes(logEntry.topic)) return;

        onLog(logEntry);
    }, []);

    // Subscribe to log events once
    useEffect(() => {
        gamingClient.addEventListener('log', handleLog);
        return () => gamingClient.removeEventListener('log', handleLog);
    }, [gamingClient, handleLog]);

    // Subscribe to player metric events once
    useEffect(() => {
        const handleMetric = (event: PublicEventsMap['playermetric']) => {
            onMetricRef.current?.(event);
        };
        gamingClient.addEventListener('playermetric', handleMetric);
        return () => gamingClient.removeEventListener('playermetric', handleMetric);
    }, [gamingClient]);

    // Subscribe to loading progress events
    useEffect(() => {
        const handleLoadingProgress = (event: PublicEventsMap['loadingprogress']) => {
            setLoadingProgress({
                step: event.step,
                stepLabel: event.stepLabel,
                progress: event.progress,
                gameLoadPercent: event.gameLoadPercent,
            });
        };

        gamingClient.addEventListener('loadingprogress', handleLoadingProgress);
        return () => gamingClient.removeEventListener('loadingprogress', handleLoadingProgress);
    }, [gamingClient]);

    // Reset loading progress when disconnecting
    useEffect(() => {
        if (!shouldInitialize) {
            setLoadingProgress({
                step: 'connecting',
                stepLabel: 'Connecting to server',
                progress: 0,
                gameLoadPercent: 0,
            });
        }
    }, [shouldInitialize]);

    // Track if we've already started to prevent duplicate starts
    const hasStartedRef = useRef(false);

    // Reset the start guard when shouldInitialize becomes false (user disconnects)
    useEffect(() => {
        if (!shouldInitialize) {
            hasStartedRef.current = false;
        }
    }, [shouldInitialize]);

    // Start game when shouldInitialize becomes true
    useEffect(() => {
        if (!shouldInitialize) return;

        // Prevent multiple concurrent starts
        if (hasStartedRef.current) return;
        hasStartedRef.current = true;

        const startGamingClient = async () => {
            try {
                if (!options.sopAccountEmail && !options.sopAccountPin) {
                    throw new StartGameError('Please select a test account to play the game', 'Invalid test account');
                }
                if (!options.sopAccountEmail || !options.sopAccountPin) {
                    throw new StartGameError(
                        'Email or PIN missing for the selected test account. Please verify and try again.',
                        'Invalid test account',
                    );
                }

                // Ensure video container exists before starting
                const videoParentElement = globalThis.document.getElementById('video_canvas') ?? undefined;
                if (!videoParentElement) {
                    throw new StartGameError(
                        'Video container not found. Please refresh the page and try again.',
                        'Video container missing',
                    );
                }

                await gamingClient.start(
                    options.sopAccountEmail,
                    options.sopAccountPin,
                    {
                        signalingServer: options.signalingServer,
                        videoParentElement,
                    },
                    options.ocgaOverrides,
                    options.controllerEnv,
                    options.testbedVersion,
                );

                await gamingClient.setGameVisibility(GameVisibility.VISIBLE);
            } catch (e) {
                onErrorRef.current?.(e as Error);
            }
        };

        startGamingClient();
    }, [
        shouldInitialize,
        gamingClient,
        options.signalingServer,
        options.sopAccountEmail,
        options.sopAccountPin,
        options.ocgaOverrides,
        options.controllerEnv,
        options.testbedVersion,
    ]);

    return { sdpDebug, loadingProgress };
}
