import { IconCaretDown } from '@hawkins/assets';
import { Button, Checkbox, MenuItem, Paper } from '@hawkins/components';
import { useCallback, useEffect, useRef, useState } from 'react';

interface PanelMenuDropdownProps {
    showGraphsNetwork: boolean;
    showLogsPanel: boolean;
    showQrPanel: boolean;
    showOverviewPanel: boolean;
    onGraphsNetworkToggle: () => void;
    onLogsToggle: () => void;
    onQrToggle: () => void;
    onOverviewToggle: () => void;
    onAllPanelsToggle: () => void;
    isPerfPopout: boolean;
    isLogsPopout: boolean;
    isQrPopout: boolean;
    isOverviewPopout: boolean;
}

export const PanelMenuDropdown = ({
    showGraphsNetwork,
    showLogsPanel,
    showQrPanel,
    showOverviewPanel,
    onGraphsNetworkToggle,
    onLogsToggle,
    onQrToggle,
    onOverviewToggle,
    onAllPanelsToggle,
    isPerfPopout,
    isLogsPopout,
    isQrPopout,
    isOverviewPopout,
}: PanelMenuDropdownProps) => {
    const [isOpen, setIsOpen] = useState(false);
    const containerRef = useRef<HTMLDivElement>(null);

    // Only non-popped-out panels contribute to the "All Panels" checked state
    const controllableStates = [
        isPerfPopout ? null : showGraphsNetwork,
        isLogsPopout ? null : showLogsPanel,
        isQrPopout ? null : showQrPanel,
        isOverviewPopout ? null : showOverviewPanel,
    ].filter((v): v is boolean => v !== null);
    const allChecked = controllableStates.every(Boolean);
    const noneChecked = controllableStates.every((v) => !v);
    const isIndeterminate = !allChecked && !noneChecked;

    useEffect(() => {
        if (!isOpen) return;
        const handleClickOutside = (e: MouseEvent) => {
            if (containerRef.current && !containerRef.current.contains(e.target as Node)) {
                setIsOpen(false);
            }
        };
        document.addEventListener('mousedown', handleClickOutside);
        return () => document.removeEventListener('mousedown', handleClickOutside);
    }, [isOpen]);

    const handleToggle = useCallback(() => setIsOpen((o) => !o), []);

    return (
        <div ref={containerRef} style={{ position: 'relative' }}>
            <Button
                variant='icon'
                compact
                icon={IconCaretDown}
                aria-label='Toggle panel visibility'
                aria-expanded={isOpen}
                aria-haspopup='menu'
                onClick={handleToggle}
                style={{
                    borderTopLeftRadius: 0,
                    borderBottomLeftRadius: 0,
                    height: 40,
                    width: 32,
                    backgroundColor: isOpen
                        ? 'var(--hawkins-theme-surface-selected-subtle)'
                        : 'var(--hawkins-theme-surface-highlight)',
                    ...(isOpen
                        ? { color: 'var(--hawkins-theme-foreground-primary)' }
                        : undefined),
                }}
            />
            {isOpen && (
                <Paper
                    elevation={2}
                    role='menu'
                    style={{
                        position: 'absolute',
                        top: 'calc(100% + 4px)',
                        right: 0,
                        zIndex: 1000,
                        minWidth: 220,
                    }}
                >
                    <MenuItem onChange={onAllPanelsToggle}>
                        <Checkbox
                            label='All Panels'
                            checked={allChecked}
                            indeterminate={isIndeterminate}
                        />
                    </MenuItem>
                    <MenuItem onChange={isPerfPopout ? undefined : onGraphsNetworkToggle} disabled={isPerfPopout}>
                        <Checkbox
                            label={isPerfPopout ? 'Session Graphs & Networks (in separate window)' : 'Session Graphs & Networks'}
                            checked={showGraphsNetwork}
                            disabled={isPerfPopout}
                        />
                    </MenuItem>
                    <MenuItem onChange={isQrPopout ? undefined : onQrToggle} disabled={isQrPopout}>
                        <Checkbox
                            label={isQrPopout ? 'NGC QR Code (in separate window)' : 'NGC QR Code'}
                            checked={showQrPanel}
                            disabled={isQrPopout}
                        />
                    </MenuItem>
                    <MenuItem onChange={isLogsPopout ? undefined : onLogsToggle} disabled={isLogsPopout}>
                        <Checkbox
                            label={isLogsPopout ? 'Logs (in separate window)' : 'Logs'}
                            checked={showLogsPanel}
                            disabled={isLogsPopout}
                        />
                    </MenuItem>
                    <MenuItem onChange={isOverviewPopout ? undefined : onOverviewToggle} disabled={isOverviewPopout}>
                        <Checkbox
                            label={isOverviewPopout ? 'Session Overview (in separate window)' : 'Session Overview'}
                            checked={showOverviewPanel}
                            disabled={isOverviewPopout}
                        />
                    </MenuItem>
                </Paper>
            )}
        </div>
    );
};
