import { useCallback, useEffect, useRef, useState } from 'react';

export const useAudioVolume = (isPlaying: boolean) => {
    const audioRef = useRef<HTMLAudioElement | null>(null);
    const [volume, setVolume] = useState(1);

    useEffect(() => {
        if (isPlaying && !audioRef.current) {
            // No <audio> element exists yet (e.g. mock play mode, which never creates a real one, or a
            // race with the real client not having mounted its audio track yet) — nothing to set.
            const audioElement = document.getElementsByTagName('audio')[0] || null;
            audioRef.current = audioElement;
            if (audioElement) {
                audioElement.volume = volume;
            }
        } else if (!isPlaying) {
            audioRef.current = null;
        }
    }, [isPlaying, volume]);

    const handleVolumeChange = useCallback((newVolume: number) => {
        setVolume(newVolume);
        if (audioRef.current) {
            audioRef.current.volume = newVolume;
        }
    }, []);

    return {
        volume,
        handleVolumeChange,
    };
};
