import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useMemo } from 'react';

export const useStreamingModeInfo = (mode: StreamingMode) => {
    return useMemo(() => {
        const isConnecting = mode === StreamingMode.WAITING_FOR_VOCGA || mode === StreamingMode.CONNECTING;
        const isDisconnected = mode === StreamingMode.CLOSED || mode === StreamingMode.INITIAL;
        const isBlocked = mode === StreamingMode.AUTOPLAY_BLOCKED;
        const isLoading = isConnecting || isBlocked;
        const isPlaying = mode === StreamingMode.OPEN;
        return {
            isConnecting,
            isDisconnected,
            isBlocked,
            isLoading,
            isPlaying,
        };
    }, [mode]);
};
