import { MultiSourceLogPanel } from '@gsm-app/components/LogViewer';
import { usePlayPage } from '../../PlayPageContext';

interface PageContentProps {
    sessionId: string | undefined;
}

export const PageContent = (props: PageContentProps) => {
    const { sessionId } = props;
    const { gameLogs, controllerLogs, playhead, onLogPlayhead, sessionStartMs } = usePlayPage();

    return (
        <MultiSourceLogPanel
            sessionId={sessionId}
            namePrefix='browser'
            gameLogs={gameLogs}
            controllerLogs={controllerLogs}
            idleMessage='No log loaded. Press Play to start a session'
            showControllerStatusBar
            defaultLayoutMode='split'
            currentTime={playhead?.time ?? null}
            sessionStartMs={sessionStartMs}
            playheadSource={playhead?.source ?? null}
            onSelectLog={onLogPlayhead}
        />
    );
};
