import { ROUTE_SESSIONS } from '@gsm-app/constants';
import { useOCGAPerfReport } from '@gsm-app/hooks/useGamePerfReport';
import { useNgpConfig } from '@gsm-app/hooks/useNgpConfig';
import type { Build } from '@gsm-app/models/Build';
import type { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useModal } from '@gsm-app/providers/ModalProvider';
import type { SopAccountType } from '@gsm-app/providers/SopAccountProvider';
import { HoverCardTooltip } from '@gsm-common/components/HoverCardTooltip';
import { keyFromOptions } from '@gsm-common/utils/dropdown/keyFromOptions';
import { formatBytes } from '@gsm-common/utils/file/formatBytes';
import {
    IconCaretDown,
    IconCircleExclamationPointFill,
    IconCircleFill,
    IconCircleI,
    IconCompare,
    IconLayout,
    IconPlay,
    IconSettings,
    IconStop,
    IconWarningFill,
} from '@hawkins/assets';
import {
    Button,
    Checkbox,
    Chip,
    Divider,
    Dropdown,
    type DropdownBaseProps,
    type DropdownOption,
    type DropdownTriggerType,
    Heading,
    HoverCard,
    type ListItemProps,
    MenuItem,
    Paper,
    SplitButton,
    Stack,
    Text,
    TextLink,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
    getFuzzyFilterOption,
} from '@hawkins/components';
import { Colors, Dimensions } from '@hawkins/variables';
import type { EnvVar } from '@ncgt/common/models/envVar';
import clsx from 'clsx';
import { forwardRef } from 'react';
import type { ForwardedRef, MouseEvent } from 'react';
import { useBuildStateProps } from '../../hooks/useBuildStateProps';
import { useStreamingModeInfo } from '../../hooks/useStreamingModeInfo';
import type { SessionSettings } from '../SessionSettingsModal/SessionSettingsModal';
import { SkeletonText } from '../SkeletonText';
import { PanelMenuDropdown } from './PanelMenuDropdown';
import styles from './PageHeader.module.css';
import { ChannelDropdownFooter } from './components/ChannelDropdown';
import { DropdownTrigger } from './components/DropdownTrigger';
import {
    SopAccountDropdownEmpty,
    SopAccountDropdownFooter,
    SopAccountDropdownItem,
} from './components/SopAccountDropdown';

interface PageHeaderProps {
    channelOptions: DropdownOption<string>[];
    gameOptions: DropdownOption<string>[];
    build: Build | undefined | null;
    mode: StreamingMode;
    areChannelsFetching: boolean | undefined;
    areChannelsRefetching: boolean | undefined;
    selectedChannelOption: DropdownOption<string> | undefined;
    selectedEnvOptions: EnvVar[] | undefined;
    sessionSettings: SessionSettings | undefined;
    selectedGameOption: DropdownOption<string> | undefined;
    sessionId: string | undefined;
    setSelectedGameOption: (value: DropdownOption<string>) => void;
    setSelectedChannelOption: (value: DropdownOption<string>) => void;
    setSelectedEnvOptions: (value: EnvVar[]) => void;
    setSessionSettings: (value: SessionSettings) => void;
    savedAccounts: SopAccountType[];
    selectedAccount: SopAccountType | undefined;
    setSelectedAccount: (value: SopAccountType) => void;
    onToggleConnection: (e: MouseEvent<HTMLButtonElement>) => void;
    viewMode: 'developer' | 'grid';
    onViewModeChange: (mode: 'developer' | 'grid') => void;
    onSettingsClick: () => void;
    isSettingsPanelOpen: boolean;
    showGraphsNetwork: boolean;
    onGraphsNetworkToggle: () => void;
    showLogsPanel: boolean;
    onLogsToggle: () => void;
    showQrPanel: boolean;
    onQrToggle: () => void;
    showOverviewPanel: boolean;
    onOverviewToggle: () => void;
    onAllPanelsToggle: () => void;
    isPerfPopout: boolean;
    isLogsPopout: boolean;
    isQrPopout: boolean;
    isOverviewPopout: boolean;
    autoPlay: boolean;
    onAutoPlayChange: (value: boolean) => void;
}

type TriggerProps<T extends DropdownOption> = DropdownBaseProps<T> & DropdownTriggerType<T, string>;

const GameTrigger = forwardRef((props: TriggerProps<DropdownOption<string>>, ref: ForwardedRef<HTMLElement>) => {
    const { onClick, onKeyDown, selected, loading, open } = props;
    const showPlaceholder = !loading && Array.isArray(selected) && selected.length === 0;
    const selectedArr = Array.isArray(selected) ? selected : [];
    const gameName = loading ? 'Loading...' : showPlaceholder ? 'Select Game' : (selectedArr[0]?.label ?? '');
    const gameId = showPlaceholder ? '' : (selectedArr[0]?.value ?? '');

    return (
        <Button
            onClick={onClick}
            onKeyDown={onKeyDown}
            ref={ref}
            variant='tertiary'
            style={{ padding: `${Dimensions.Space4} ${Dimensions.Space8}`, height: '100%' }}
        >
            <Stack orientation='horizontal' gap={Dimensions.Space8} style={{ alignItems: 'center' }}>
                <div className={styles.gameIcon} />
                <Stack orientation='vertical' gap={0} style={{ alignItems: 'flex-start' }}>
                    <Text variant='label' colorVariant='faded' className={styles.gameIdLabel} component='div'>
                        {showPlaceholder ? 'No game selected' : `Game ID: ${gameId}`}
                    </Text>
                    <Stack orientation='horizontal' gap={Dimensions.Space4} style={{ alignItems: 'center' }}>
                        <span className={styles.gameName}>{gameName}</span>
                        {open ? (
                            <IconCaretDown size='small' style={{ transform: 'rotate(180deg)' }} />
                        ) : (
                            <IconCaretDown size='small' />
                        )}
                    </Stack>
                </Stack>
            </Stack>
        </Button>
    );
}) as (props: TriggerProps<DropdownOption<string>> & { ref?: ForwardedRef<HTMLElement> }) => JSX.Element;

const ChannelTrigger = forwardRef((props: TriggerProps<DropdownOption<string>>, ref: ForwardedRef<HTMLElement>) => (
    <DropdownTrigger {...props} hideSubtitle titleMaxWidth={160} ref={ref} />
));

const AccountTrigger = forwardRef((props: TriggerProps<SopAccountType>, ref: ForwardedRef<HTMLElement>) => (
    <DropdownTrigger {...props} hideSubtitle titleMaxWidth={160} ref={ref} />
));

const testReportClassname = (state: string) => {
    if (state === 'PENDING' || state === 'QUEUED') {
        return styles.stateAnimated;
    }
    return '';
};

const testReportColorByState = (state: string) => {
    switch (state) {
        case 'PENDING':
            return Colors.Blue;
        case 'ERROR':
            return Colors.Red;
        case 'FAILED':
            return Colors.Red;
        case 'ABORTED':
            return Colors.Orange;
        case 'RUNNING':
            return Colors.Indigo;
        case 'SUCCEEDED':
            return Colors.Green;
        case 'QUEUED':
            return Colors.Blue;
        default:
            return Colors.Gray;
    }
};

export const SessionSettingsLabels: { [name: string]: string } = {
    ocgaSteeringOverride: 'OCGA Steering Override',
    hardwareVersionSelection: 'Hardware Selection',
    softwareGameDevPool: 'Software Version Selection',
    resolutionOverride: 'Resolution Override',
    fpsOverride: 'FPS Override',
};

const SOFTWARE_POOL_HOVER_LABELS: Record<string, string> = {
    GAME_DEV_POOL_OFFICIAL: 'Current',
    GAME_DEV_POOL_PREVIEW: 'Preview',
    GAME_DEV_POOL_PREVIOUS: 'Previous',
};

export const PageHeader = ({
    channelOptions,
    gameOptions,
    build,
    mode,
    areChannelsFetching,
    areChannelsRefetching,
    selectedChannelOption,
    selectedEnvOptions,
    selectedGameOption,
    sessionSettings,
    sessionId,
    setSelectedGameOption,
    setSelectedEnvOptions,
    setSelectedChannelOption,
    setSessionSettings,
    savedAccounts,
    selectedAccount,
    setSelectedAccount,
    onToggleConnection,
    viewMode,
    onViewModeChange,
    onSettingsClick,
    isSettingsPanelOpen,
    showGraphsNetwork,
    onGraphsNetworkToggle,
    showLogsPanel,
    onLogsToggle,
    showQrPanel,
    onQrToggle,
    showOverviewPanel,
    onOverviewToggle,
    onAllPanelsToggle,
    isPerfPopout,
    isLogsPopout,
    isQrPopout,
    isOverviewPopout,
    autoPlay,
    onAutoPlayChange,
}: PageHeaderProps) => {
    const { showModal } = useModal();
    const { isDisconnected } = useStreamingModeInfo(mode);
    const {
        data: ocgaPerfReport,
        error: ocgaPerfReportError,
        isFetched: isPerfReportFetched,
        isLoading: isPerfReportLoading,
    } = useOCGAPerfReport(selectedGameOption?.value, build?.id ?? undefined);

    const buildStateProps = useBuildStateProps(build);

    const envVariableTotal = Number(selectedEnvOptions?.length ?? 0);

    const ngpConfig = useNgpConfig(selectedGameOption?.value);

    return (
        <>
            <div className={styles.header}>
                {/* Game selector */}
                <Dropdown<DropdownOption<string>>
                    DropdownTrigger={GameTrigger}
                    label={`Game ID: ${selectedGameOption?.value ?? ''}`}
                    onChange={(selected) => {
                        if (selected) setSelectedGameOption(selected);
                    }}
                    options={gameOptions}
                    loading={gameOptions.length === 0}
                    value={selectedGameOption}
                    getOptionValue={(option) => {
                        if (typeof option === 'string') return option;
                        return option.value;
                    }}
                    searchable={gameOptions.length > 5}
                    clearSearchOnSelect
                    filterOptions={getFuzzyFilterOption(gameOptions, {
                        keys: ['label', 'subtitle'],
                        ignoreLocation: true,
                    })}
                    key={`games-${keyFromOptions(gameOptions)}`}
                    disabled={!isDisconnected}
                    style={{ width: 'auto' }}
                    dropdownWidthType={320}
                />

                <Divider variant='vertical' className={styles.divider} />

                {/* View mode toggle: Player View / Dev View + panel visibility caret */}
                <div className='sr-view-mode-control'>
                    <div className='sr-toggle-flat'>
                        <ToggleButtonGroup
                            compact
                            exclusive
                            value={viewMode === 'developer' ? 'layout' : 'grid'}
                            onChange={(_ev, value) => {
                                if (value === 'grid') onViewModeChange('grid');
                                else if (value === 'layout') onViewModeChange('developer');
                            }}
                        >
                            <ToggleButton value='grid' icon={IconCompare}>
                                Player View
                            </ToggleButton>
                            <ToggleButton value='layout' icon={IconLayout}>
                                Dev View
                            </ToggleButton>
                        </ToggleButtonGroup>
                    </div>
                    {viewMode === 'developer' && (
                        <PanelMenuDropdown
                            showGraphsNetwork={showGraphsNetwork}
                            showLogsPanel={showLogsPanel}
                            showQrPanel={showQrPanel}
                            onGraphsNetworkToggle={onGraphsNetworkToggle}
                            onLogsToggle={onLogsToggle}
                            onQrToggle={onQrToggle}
                            showOverviewPanel={showOverviewPanel}
                            onOverviewToggle={onOverviewToggle}
                            onAllPanelsToggle={onAllPanelsToggle}
                            isPerfPopout={isPerfPopout}
                            isLogsPopout={isLogsPopout}
                            isQrPopout={isQrPopout}
                            isOverviewPopout={isOverviewPopout}
                        />
                    )}
                </div>
                {/* Spacer pushes right-aligned items to the right */}
                <div className={styles.spacer} />

                {/* Session info chips */}
                <Stack orientation='vertical' gap={2} className={styles.sessionChips}>
                    <Tooltip
                        label={sessionId ? `Session ID: ${sessionId}` : "Session ID: Press 'Play' to generate"}
                    >
                        <Chip
                            compact
                            onClick={() => {
                                if (sessionId) window.open(`${ROUTE_SESSIONS}/${sessionId}`, '_blank');
                            }}
                            style={{ cursor: sessionId ? 'pointer' : undefined }}
                            className={styles.chip}
                        >
                            <span className={styles.chipText}>
                                {sessionId ? `Session ID: ${sessionId}` : "Session ID: Press 'Play' to generate"}
                            </span>
                        </Chip>
                    </Tooltip>

                    {!ocgaPerfReport?.state ? (
                        <Tooltip label='No OCGA Perf Report'>
                            <Chip
                                compact
                                className={styles.chip}
                                loading={(!isPerfReportFetched || isPerfReportLoading) && !ocgaPerfReportError}
                            >
                                <span className={styles.chipText}>No OCGA Perf Report</span>
                            </Chip>
                        </Tooltip>
                    ) : (
                        <HoverCardTooltip
                            disabled={ocgaPerfReport?.state !== 'SUCCEEDED'}
                            label={['Performance Report created on', 'OCGA Instance Count', 'Report']}
                            description={[
                                new Date(ocgaPerfReport.createTime).toLocaleString(),
                                ocgaPerfReport.instanceCount > 0 ? ocgaPerfReport.instanceCount : 'Error',
                                <TextLink
                                    key='testLink'
                                    href={ocgaPerfReport.testLink}
                                    variant='standalone'
                                    target='_blank'
                                    noWrap
                                    style={{ width: 250 }}
                                >
                                    Open test report
                                </TextLink>,
                            ]}
                            interactive
                        >
                            <Chip compact className={styles.chip}>
                                <Stack gap={Dimensions.RawSpace4} orientation='horizontal'>
                                    <Text component='div' variant='label' level={0}>
                                        <Tooltip label={ocgaPerfReport.state}>
                                            <IconCircleFill
                                                className={testReportClassname(ocgaPerfReport.state)}
                                                width={Dimensions.RawSize8}
                                                height={Dimensions.RawSize8}
                                                style={{ marginRight: Dimensions.Space4 }}
                                                color={testReportColorByState(ocgaPerfReport.state)}
                                            />
                                        </Tooltip>
                                        {ocgaPerfReport.instanceCount
                                            ? `OCGA Report (${ocgaPerfReport.instanceCount})`
                                            : 'OCGA Report'}
                                    </Text>
                                </Stack>
                            </Chip>
                        </HoverCardTooltip>
                    )}
                </Stack>

                <Divider variant='vertical' className={styles.divider} />

                {/* Channel & Build dropdown */}
                <Dropdown
                    DropdownTrigger={ChannelTrigger}
                    label={
                        <Stack
                            component='span'
                            orientation='horizontal'
                            style={{ alignItems: 'center' }}
                            gap={Dimensions.RawSpace4}
                        >
                            <Text variant='label' level={0} component='div' colorVariant='faded'>
                                Channel
                            </Text>
                            {build && (
                                <span className={styles.buildIcon}>
                                    <HoverCard interactive>
                                        <HoverCard.Trigger>
                                            {!build || buildStateProps.playable ? (
                                                <IconCircleI
                                                    size='small'
                                                    aria-label='buildinfo'
                                                    key={`buildinfo_${buildStateProps.value}`}
                                                />
                                            ) : (
                                                <IconCircleExclamationPointFill
                                                    size='small'
                                                    aria-label='buildinfo'
                                                    key={`buildinfo_${buildStateProps.value}`}
                                                    fill='var(--icon-fill-information-error)'
                                                />
                                            )}
                                        </HoverCard.Trigger>
                                        <HoverCard.Content>
                                            <Paper>
                                                <Heading level={0}>Build Details</Heading>
                                                <Text colorVariant='faded'>ID: {build?.id ?? 'N/A'}</Text>
                                                <div style={{ display: 'flex' }}>
                                                    <SkeletonText
                                                        label={'Status:'}
                                                        labelProps={{ colorVariant: 'faded' }}
                                                        value={buildStateProps.value ?? 'N/A'}
                                                        color={buildStateProps.color}
                                                        width='130px'
                                                    />
                                                </div>
                                                <Text colorVariant='faded'>
                                                    {`Last update: ${
                                                        build?.updatedDate
                                                            ? new Date(build.updatedDate).toLocaleString()
                                                            : 'N/A'
                                                    }`}
                                                </Text>
                                                <Text colorVariant='faded'>
                                                    Updated By: {build?.submitter ?? 'N/A'}
                                                </Text>
                                                <Text colorVariant='faded'>Size: {formatBytes(build?.size)}</Text>
                                            </Paper>
                                        </HoverCard.Content>
                                    </HoverCard>
                                </span>
                            )}
                        </Stack>
                    }
                    onChange={(selected) => {
                        if (selected) setSelectedChannelOption(selected);
                    }}
                    groupBy={(option) => option.group ?? ''}
                    sortGroups={(a, b) => {
                        if (a === 'Playable' && b === 'Upload required') return -1;
                        if (a === 'Upload required' && b === 'Playable') return 1;
                        return 0;
                    }}
                    options={channelOptions}
                    loading={channelOptions.length === 0}
                    value={selectedChannelOption}
                    showRecentlySelected='only-when-empty-query'
                    recentlySelectedGroupLabel='Recent selections'
                    searchable={channelOptions.length > 5}
                    filterOptions={getFuzzyFilterOption(channelOptions, { keys: ['label', 'subtitle', 'buildId'] })}
                    getOptionSubtitle={(option) => option?.subtitle}
                    key={`channels-${keyFromOptions(channelOptions)}`}
                    disabled={!isDisconnected}
                    style={{ width: 'auto' }}
                    dropdownWidthType={320}
                    DropdownListFooter={() => {
                        return channelOptions.length ? <ChannelDropdownFooter /> : <></>;
                    }}
                />

                <Divider variant='vertical' className={styles.divider} />

                {/* Test account dropdown */}
                <Dropdown<SopAccountType>
                    DropdownTrigger={AccountTrigger}
                    label='Test Account'
                    onChange={(selected: SopAccountType | null) => {
                        if (selected) setSelectedAccount(selected);
                    }}
                    groupBy={() => 'Saved Logins'}
                    options={savedAccounts}
                    value={selectedAccount}
                    key={`login-as-${keyFromOptions(savedAccounts)}`}
                    disabled={!isDisconnected}
                    style={{ width: 'auto' }}
                    dropdownWidthType={280}
                    position={'bottom-end'}
                    DropdownListEmptySuggestion={() => <SopAccountDropdownEmpty />}
                    DropdownListItem={(props: ListItemProps<SopAccountType>) => <SopAccountDropdownItem {...props} />}
                    DropdownListFooter={() => {
                        return savedAccounts.length ? <SopAccountDropdownFooter /> : <></>;
                    }}
                />

                <Divider variant='vertical' className={styles.divider} />

                {/* Session settings override indicator */}
                {Object.keys(sessionSettings || {}).length > 0 && (
                    <HoverCard>
                        <HoverCard.Trigger>
                            <Button compact className={clsx(styles.chip, styles.warning)} onClick={onSettingsClick}>
                                <IconWarningFill size='small' />
                                Override
                            </Button>
                        </HoverCard.Trigger>
                        <HoverCard.Content>
                            <Paper elevation={2}>
                                <Stack gap={Dimensions.Space8}>
                                    {Object.keys(sessionSettings || {}).map((key) => (
                                        <Stack key={key}>
                                            <Heading level={0}>{SessionSettingsLabels[key]}</Heading>
                                            <Text>{sessionSettings?.[key as keyof SessionSettings]}</Text>
                                        </Stack>
                                    ))}
                                </Stack>
                            </Paper>
                        </HoverCard.Content>
                    </HoverCard>
                )}

                {/* Play / Stop split button */}
                <SplitButton
                    primaryActionLabel={isDisconnected ? 'Play' : 'Stop'}
                    primaryActionHandler={onToggleConnection}
                    icon={isDisconnected ? IconPlay : IconStop}
                    variant='primary'
                    buttonProps={!isDisconnected ? { variant: 'primary-destructive' } : undefined}
                    menuTriggerProps={!isDisconnected ? { variant: 'primary-destructive' } : undefined}
                    primaryActionDisabled={Boolean(
                        !selectedGameOption || !selectedChannelOption || areChannelsFetching,
                    )}
                    executing={areChannelsRefetching}
                >
                    <MenuItem onChange={() => onAutoPlayChange(!autoPlay)} disabled={!isDisconnected}>
                        <Checkbox label='Auto Play' checked={autoPlay} disabled={!isDisconnected} />
                    </MenuItem>
                </SplitButton>

                {/* Settings icon button — highlighted when panel is open */}
                <Tooltip label='Toggle session settings for OCGA steering, video settings and environment variables.'>
                    <Button
                        aria-label='Settings'
                        icon={IconSettings}
                        variant='icon'
                        onClick={onSettingsClick}
                        style={
                            isSettingsPanelOpen
                                ? {
                                      backgroundColor: 'var(--hawkins-theme-surface-highlight)',
                                      color: 'var(--hawkins-theme-foreground-primary)',
                                      borderRadius: 'var(--hawkins-dimensions-border-radius-4)',
                                  }
                                : undefined
                        }
                    />
                </Tooltip>
            </div>
        </>
    );
};
