import { useFeature } from '@gsm-app/hooks/useFeature';
import { useCallback, useEffect, useState } from 'react';

type NavigatorKeyboard = Navigator & {
    keyboard: {
        lock: (keys: any) => any;
        unlock: () => any;
    };
};

const isKeyboardSupported = (nav: any): nav is NavigatorKeyboard => {
    return nav.keyboard?.lock !== undefined;
};

export const useFullScreen = (element?: HTMLElement) => {
    const [ref, setRef] = useState(element ?? null);
    const [fullscreen, setFullscreen] = useState(Boolean(document.fullscreenElement));
    const { headless } = useFeature();

    const requestFullscreen = useCallback(() => {
        if (!fullscreen) {
            if (headless) {
                try {
                    // @ts-ignore
                    globalThis.window.AppAPI.send('request-fullscreen');
                    setFullscreen(true);
                } catch (error) {
                    console.log('Error sending request-fullscreen:', error);
                }
            } else {
                ref?.requestFullscreen?.();
            }
        }
    }, [fullscreen, ref, headless]);

    const exitFullscreen = useCallback(() => {
        if (fullscreen) {
            if (headless) {
                try {
                    // @ts-ignore
                    globalThis.window.AppAPI.send('exit-fullscreen');
                    setFullscreen(false);
                } catch (error) {
                    console.log('Error sending exit-fullscreen:', error);
                }
            } else {
                document.exitFullscreen?.();
            }
        }
    }, [fullscreen, headless]);

    const toggleFullscreen = useCallback(() => {
        if (fullscreen) {
            exitFullscreen();
        } else {
            requestFullscreen();
        }
    }, [fullscreen, requestFullscreen, exitFullscreen]);

    useEffect(() => {
        const handleKeyDown = (e: KeyboardEvent) => {
            // exit fullscreen on shift + tab
            if (e.code === 'Tab') {
                if (e.shiftKey) {
                    exitFullscreen();
                }
                e.preventDefault();
            }
        };
        if (fullscreen) {
            document.addEventListener('keydown', handleKeyDown);
        }
        return () => {
            document.removeEventListener('keydown', handleKeyDown);
        };
    }, [fullscreen]);

    useEffect(() => {
        const handleFullscreenChange = async (e: Event) => {
            const isFullScreen = Boolean(document.fullscreenElement);
            // require holding escape if keyboard lock is supported by the browser
            if (isKeyboardSupported(navigator)) {
                if (isFullScreen) {
                    await navigator.keyboard.lock(['Escape']);
                } else {
                    navigator.keyboard.unlock();
                }
            }
            setFullscreen(() => isFullScreen);
        };
        document.addEventListener('fullscreenchange', handleFullscreenChange);
        return () => {
            document.removeEventListener('fullscreenchange', handleFullscreenChange);
        };
    }, []);

    return {
        ref,
        setRef,
        fullscreen,
        requestFullscreen,
        exitFullscreen,
        toggleFullscreen,
    };
};
