import type { OcgaPerformanceReport } from '@gsm-app/models/GamePerfReport';
import { fetch } from '@gsm-app/utils/fetch';
import { useQuery } from '@tanstack/react-query';

export const useOCGAPerfReport = (gameId: number | string | undefined, buildId: string | undefined) => {
    return useQuery<OcgaPerformanceReport>({
        queryKey: ['ocgaperfreport', gameId, buildId],
        queryFn: async () => {
            if (gameId && buildId) {
                try {
                    const response = await fetch(`/api/games/${gameId}/builds/${buildId}/ocgaperfreport`);

                    // If the response is 404, return an empty array
                    if (response.status === 404) {
                        return [];
                    }

                    // Attempt to parse the JSON response
                    const data = await response.json();

                    // If there are errors in the response, throw a detailed error
                    if (data.errors && data.errors.length > 0) {
                        const error = data.errors[0];
                        // Construct a detailed error message
                        const errorMessage = `Error ${error.status} - ${error.title}: ${error.detail}`;
                        throw new Error(errorMessage);
                    }

                    // Return the data if everything is fine
                    return data.data;
                } catch (error) {
                    console.error('Failed to fetch OCGAPerfReport:', error);
                    throw error; // Re-throw the error to be handled by React Query
                }
            }
            return [];
        },
    });
};
