import { MockGameplayPlaceholder } from '@gsm-app/mocks/MockGameplayPlaceholder';
import { isMockPlayMode } from '@gsm-app/mocks/mockPlayMode';
import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useModal } from '@gsm-app/providers/ModalProvider';
import { useFullScreen } from '@gsm-common/hooks/useFullScreen';
import { useScreenshot } from '@gsm-common/hooks/useScreenshot';
import { useVideoCapture } from '@gsm-common/hooks/useVideoCapture';
import { IconUpload } from '@hawkins/assets';
import { Button, Centered, ContextualBanner } from '@hawkins/components';
import type { LoadingProgress } from '@ncgt/player';
import clsx from 'clsx';
import type { MouseEvent } from 'react';
import { useLayoutEffect } from 'react';
import styles from './PagePlayer.module.css';
import { PlayerToolbar } from './components/PlayerToolbar';
import { VideoLoader } from './components/VideoLoader';

interface PagePlayerProps {
    disabled: boolean;
    loading: boolean;
    mode: StreamingMode;
    failedMessage: string | undefined;
    fullWindow?: boolean;
    onToggleConnection?: (e: MouseEvent<HTMLButtonElement>) => any;
    loadingProgress?: LoadingProgress;
}

export const PagePlayer = ({
    disabled,
    loading,
    mode,
    failedMessage,
    fullWindow = false,
    onToggleConnection,
    loadingProgress,
}: PagePlayerProps) => {
    const { showModal } = useModal();
    const { setRef: setPlayerRef, ref: playerRef, fullscreen, toggleFullscreen } = useFullScreen();
    const { capture: captureImage } = useScreenshot(playerRef);
    const { stop: stopVideoCapture, state: videoState, toggle: toggleVideoCapture } = useVideoCapture(playerRef);

    // stop recording when game is stoped
    if (mode === StreamingMode.CLOSED && videoState === 'recording') {
        stopVideoCapture();
    }

    // stop recording when unmounted
    useLayoutEffect(() => stopVideoCapture, [stopVideoCapture]);

    return (
        <Centered style={{ flexDirection: 'column', height: '100%' }}>
            <div className={styles.playerGroup}>
                <div className={styles.playerContainer} ref={setPlayerRef}>
                    <div
                        className={clsx(styles.videoCanvas, {
                            [styles.fullscreen]: fullscreen,
                            [styles.fullWindow]: fullWindow,
                        })}
                        id='video_canvas'
                    >
                        {isMockPlayMode && mode === StreamingMode.OPEN && <MockGameplayPlaceholder />}
                    </div>
                    <VideoLoader loading={loading} mode={mode} loadingProgress={loadingProgress} />
                    {failedMessage && (
                        <div className={styles.bannerContainer}>
                            <ContextualBanner
                                text={failedMessage}
                                title='Error'
                                variant='error'
                                fullWidth
                                customActionPlacement='right'
                                customActions={[
                                    <Button
                                        key='upload'
                                        icon={IconUpload}
                                        variant='tertiary'
                                        onClick={() => showModal('uploadBuild')}
                                    >
                                        Upload Build
                                    </Button>,
                                ]}
                            />
                        </div>
                    )}
                </div>
                <PlayerToolbar
                    disabled={disabled}
                    mode={mode}
                    fullscreen={fullscreen}
                    fullWindow={fullWindow}
                    onScreenshot={captureImage}
                    onToggleFullscreen={toggleFullscreen}
                    onToggleConnection={onToggleConnection}
                    onToggleVideoCapture={toggleVideoCapture}
                    videoCaptureState={videoState}
                />
            </div>
        </Centered>
    );
};
