import { useEffect, useState } from 'react';
import { MOCK_GAMEPLAY_ROTATE_INTERVAL_MS, MOCK_GAMEPLAY_SCREENS } from './mockGameplayScreens';

/**
 * Local-only UI dev mode — there's no real video track to show once a mock session is "playing"
 * (see MockBrowserGamingClient), so this cycles through a handful of static screenshots instead of
 * leaving the video area a flat black box. Purely cosmetic; carries no session data.
 *
 * The displayed index is derived from wall-clock time (not an incrementing counter) so it stays in
 * lockstep with `useMockPeriodicScreenshots`, which independently computes "what was on screen" at
 * a given capture moment via the same `getMockScreenAt` helper.
 */
export const MockGameplayPlaceholder = () => {
    const [index, setIndex] = useState(() => Math.floor(Date.now() / MOCK_GAMEPLAY_ROTATE_INTERVAL_MS) % MOCK_GAMEPLAY_SCREENS.length);

    useEffect(() => {
        const interval = setInterval(() => {
            setIndex(Math.floor(Date.now() / MOCK_GAMEPLAY_ROTATE_INTERVAL_MS) % MOCK_GAMEPLAY_SCREENS.length);
        }, MOCK_GAMEPLAY_ROTATE_INTERVAL_MS);
        return () => clearInterval(interval);
    }, []);

    return (
        <div
            style={{
                position: 'absolute',
                inset: 0,
                overflow: 'hidden',
            }}
        >
            {MOCK_GAMEPLAY_SCREENS.map((src, i) => (
                <img
                    key={src}
                    src={src}
                    alt=''
                    style={{
                        position: 'absolute',
                        inset: 0,
                        width: '100%',
                        height: '100%',
                        objectFit: 'cover',
                        opacity: i === index ? 1 : 0,
                        transition: 'opacity 600ms ease',
                    }}
                />
            ))}
        </div>
    );
};
