import NetworkActivityTable from '@gsm-app/components/NetworkActivityTable/NetworkActivityTable';
import { SSICQrCode } from '@gsm-app/components/SSICQrCode';
import { IconLinkOut, IconX } from '@hawkins/assets';
import type { DockviewApi, IDockviewPanelHeaderProps, IDockviewPanelProps } from 'dockview';
import type React from 'react';
import { usePlayPage } from '../PlayPageContext';
import { PageContent } from './PageContent/PageContent';
import { PagePlayer } from './PagePlayer/PagePlayer';
import { SessionOverviewPanel } from './SessionOverviewPanel/SessionOverviewPanel';
import { SessionPerfPanel } from './SessionPerfPanel/SessionPerfPanel';
import { SettingsPanel } from './SettingsPanel/SettingsPanel';

// ── Panel wrapper components — read live state from context ──────────────────

export const PerfPanelView = (_: IDockviewPanelProps) => {
    const {
        sessionId,
        mode,
        screenshots,
        enforceEnvelope,
        onEnforceEnvelopeChange,
        gameLogs,
        controllerLogs,
        playhead,
        onGraphPlayhead,
        sessionStartMs,
    } = usePlayPage();
    return (
        <SessionPerfPanel
            sessionId={sessionId}
            mode={mode}
            screenshots={screenshots}
            enforceEnvelope={enforceEnvelope}
            onEnforceEnvelopeChange={onEnforceEnvelopeChange}
            gameLogsData={gameLogs.data}
            controllerLogsData={controllerLogs.data}
            currentTime={playhead?.time ?? null}
            sessionStartMs={sessionStartMs}
            playheadSource={playhead?.source ?? null}
            onGraphPlayhead={onGraphPlayhead}
        />
    );
};

export const PlayerPanelView = (_: IDockviewPanelProps) => {
    const { isLoading, mode, failedMessage, toggleConnection, selectedGame, selectedChannel, loadingProgress } =
        usePlayPage();
    return (
        <PagePlayer
            loading={isLoading}
            mode={mode}
            failedMessage={failedMessage}
            onToggleConnection={toggleConnection}
            disabled={Boolean(!selectedGame || !selectedChannel)}
            loadingProgress={loadingProgress}
        />
    );
};

export const LogsPanelView = (_: IDockviewPanelProps) => {
    const { sessionId } = usePlayPage();
    return <PageContent sessionId={sessionId} />;
};

export const QrCodePanelView = (_: IDockviewPanelProps) => {
    const {
        mode,
        qrCodeUrl,
        passport,
        showSSIC,
        setShowSSIC,
        controllerEnv,
        setControllerEnv,
        ssicWindowConfig,
        sideloadedControllerUrl,
        setSsicWindowConfig,
        controllerOptions,
        selectedController,
        setSelectedController,
        testbedVersion,
        setTestbedVersion,
    } = usePlayPage();
    return (
        <SSICQrCode
            hideToolbar
            mode={mode}
            qrCodeUrl={qrCodeUrl}
            passport={passport}
            showSSIC={showSSIC}
            setShowSSIC={setShowSSIC}
            controllerEnv={controllerEnv}
            setControllerEnv={setControllerEnv}
            ssicWindowConfig={ssicWindowConfig}
            sideloadedControllerUrl={sideloadedControllerUrl}
            setSsicWindowConfig={setSsicWindowConfig}
            controllerOptions={controllerOptions}
            selectedController={selectedController}
            setSelectedController={setSelectedController}
            testbedVersion={testbedVersion}
            setTestbedVersion={setTestbedVersion}
        />
    );
};

export const NetworkPanelView = (_: IDockviewPanelProps) => {
    const { sessionId, selectedGame } = usePlayPage();
    const gameId = selectedGame?.value ? Number(selectedGame.value) : undefined;
    return <NetworkActivityTable gameId={gameId} sessionId={sessionId} />;
};

export const SessionOverviewPanelView = (_: IDockviewPanelProps) => {
    return <SessionOverviewPanel />;
};

export const SettingsPanelView = (props: IDockviewPanelProps) => {
    const { isDisconnected, selectedGame, selectedEnvOptions, setSessionSettings, setSelectedEnvOptions } =
        usePlayPage();
    return (
        <SettingsPanel
            playing={!isDisconnected}
            gameId={selectedGame?.value ?? ''}
            selectedEnvOptions={selectedEnvOptions}
            onSaveSettings={setSessionSettings}
            onSaveEnvVars={setSelectedEnvOptions}
            onClose={() => props.api.close()}
        />
    );
};

// ── Components map passed to DockviewReact ───────────────────────────────────

export const DOCK_COMPONENTS = {
    perf: PerfPanelView,
    network: NetworkPanelView,
    player: PlayerPanelView,
    logs: LogsPanelView,
    qr: QrCodePanelView,
    overview: SessionOverviewPanelView,
    settings: SettingsPanelView,
};

// ── Custom tab header with float + close buttons ─────────────────────────────

const tabBtnStyle: React.CSSProperties = {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    width: 20,
    height: 20,
    background: 'none',
    border: 'none',
    cursor: 'pointer',
    borderRadius: 3,
    padding: 0,
    color: 'rgba(255,255,255,0.5)',
    flexShrink: 0,
};

const PINNED_PANELS = new Set(['player']);

function injectStylesIntoWindow(targetWindow: Window): void {
    const doc = targetWindow.document;
    document.querySelectorAll('link[rel="stylesheet"], style').forEach((node) => {
        doc.head.appendChild(node.cloneNode(true));
    });
}

export const DockTabHeader = ({ api, containerApi }: IDockviewPanelHeaderProps) => {
    const isPinned = PINNED_PANELS.has(api.id);

    const handlePopout = () => {
        const panel = containerApi.getPanel(api.id);
        if (!panel) return;
        const { onPopout } = api.getParameters<{
            onPopout?: (panelId: string, isPopped: boolean) => void;
        }>();
        onPopout?.(api.id, true);
        containerApi.addPopoutGroup(panel, {
            onDidOpen: ({ window: popoutWindow }) => {
                injectStylesIntoWindow(popoutWindow);
            },
            onWillClose: () => {
                onPopout?.(api.id, false);
            },
        });
    };

    return (
        <div style={{ display: 'flex', alignItems: 'center', gap: 2, height: '100%', padding: '0 6px', minWidth: 0 }}>
            <span
                style={{
                    fontFamily: 'var(--hawkins-typography-font-family-sans)',
                    fontSize: 'var(--hawkins-typography-font-size-10)',
                    fontWeight: 'var(--hawkins-typography-font-weight-500)',
                    lineHeight: 'var(--hawkins-typography-line-height-1-5)',
                    color: 'var(--hawkins-theme-foreground)',
                    whiteSpace: 'nowrap',
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    flex: 1,
                }}
            >
                {api.title}
            </span>
            {!isPinned && (
                <button style={tabBtnStyle} title='Pop out panel' onClick={handlePopout}>
                    <IconLinkOut width={12} height={12} />
                </button>
            )}
            {!isPinned && (
                <button
                    style={tabBtnStyle}
                    title='Close panel'
                    onClick={() => containerApi.getPanel(api.id)?.group.api.setVisible(false)}
                >
                    <IconX width={12} height={12} />
                </button>
            )}
        </div>
    );
};

// ── Fixed-width panels ───────────────────────────────────────────────────────
//
// The `perf` and `qr` panels should keep a fixed pixel width whenever the
// layout changes for reasons *other than* a user dragging the sash — e.g.:
//   • browser window resize  (container width changes)
//   • settings/network panel toggled in/out  (total panel count changes)
//
// We distinguish those "external" changes from "user sash drag" by tracking
// both `api.width` (container size) and `api.totalPanels` (panel count).
// Only when both are unchanged do we treat the change as a user drag and
// persist the new widths as the desired stored widths.
//
// Dockview's own proportional-resize RAF fires inside the ResizeObserver
// callback, so our corrective `setSize()` call is issued in a second RAF
// which runs *after* Dockview's RAF has already updated the panel sizes.

const FIXED_PANELS: Array<{ id: string; defaultWidth: number }> = [
    { id: 'perf', defaultWidth: 550 },
    { id: 'qr', defaultWidth: 230 },
];

export function setupFixedPanelWidths(api: DockviewApi): void {
    const storedWidths: Record<string, number> = {};
    for (const { id, defaultWidth } of FIXED_PANELS) {
        storedWidths[id] = defaultWidth;
    }

    function restoreFixedWidths() {
        for (const { id } of FIXED_PANELS) {
            const panel = api.getPanel(id);
            const stored = storedWidths[id];
            if (panel && stored && panel.group.api.isVisible) {
                panel.group.api.setSize({ width: stored });
            }
        }
    }

    // `api.width` is 0 at setup time (layout hasn't been called yet).
    // Both values are updated on the first `onDidLayoutChange` event.
    let prevContainerWidth = api.width;
    let prevTotalPanels = api.totalPanels;

    api.onDidLayoutChange(() => {
        const currentContainerWidth = api.width;
        const currentTotalPanels = api.totalPanels;

        const containerResized = currentContainerWidth !== prevContainerWidth;
        const panelCountChanged = currentTotalPanels !== prevTotalPanels;

        prevContainerWidth = currentContainerWidth;
        prevTotalPanels = currentTotalPanels;

        if (containerResized || panelCountChanged) {
            // External change — restore fixed panels to their stored widths.
            // Use RAF so Dockview's own proportional layout runs first.
            requestAnimationFrame(restoreFixedWidths);
            return;
        }

        // Container and panel count both unchanged → user dragged a sash.
        // Persist the new widths so future restores honour the drag result.
        for (const { id } of FIXED_PANELS) {
            const panel = api.getPanel(id);
            if (panel && panel.group.api.isVisible && panel.group.api.width > 0) {
                storedWidths[id] = panel.group.api.width;
            }
        }
    });
}

// ── Default layout ───────────────────────────────────────────────────────────

export function setupDefaultLayout(api: DockviewApi): void {
    const playerPanel = api.addPanel({ id: 'player', component: 'player', title: 'Game' });
    playerPanel.group.element.classList.add('game-group');
    api.addPanel({
        id: 'perf',
        component: 'perf',
        title: 'Performance',
        position: { direction: 'left', referencePanel: 'player' },
        initialWidth: 550,
    });
    const logsPanel = api.addPanel({
        id: 'logs',
        component: 'logs',
        title: 'Logs',
        position: { direction: 'below', referencePanel: 'player' },
    });
    logsPanel.group.element.classList.add('logs-group');
    const qrPanel = api.addPanel({
        id: 'qr',
        component: 'qr',
        title: 'NGC QR Code',
        position: { direction: 'left', referencePanel: 'logs' },
        initialWidth: 230,
    });
    qrPanel.group.element.classList.add('logs-group');
    api.addPanel({
        id: 'overview',
        component: 'overview',
        title: 'Session Overview',
        position: { direction: 'right', referencePanel: 'player' },
        initialWidth: 280,
    });
}
