import { createError } from '@gsm-common/utils/toast/createError';
import { useQuery } from '@tanstack/react-query';
import { useEffect } from 'react';

const PASSPORT_KEY = 'passport';

async function fetchPassport({
    signal,
    sopAccountEmail,
    clientId,
}: {
    signal: AbortSignal;
    sopAccountEmail?: string;
    clientId?: string;
}) {
    const response = await fetch('/api/access/passport', {
        signal,
        method: 'POST',
        headers: {
            'Content-Type': 'application/json',
        },
        body: JSON.stringify({
            sopAccountEmail,
            clientId,
        }),
    });

    if (!response.ok) {
        const errorData = await response.text();
        throw new Error(`Fetch failed with status ${response.status}: ${errorData}`);
    }
    return response.json() as Promise<{ data: string }>;
}

export const usePassport = (sopAccountEmail?: string, clientId?: string) => {
    const query = useQuery({
        queryKey: [PASSPORT_KEY, sopAccountEmail, clientId],
        queryFn: ({ signal }) => fetchPassport({ signal, sopAccountEmail, clientId }),
        enabled: Boolean(sopAccountEmail),
    });

    const { error, isError } = query;
    const devMode = process.env.NODE_ENV === 'development';

    useEffect(() => {
        if (isError && !devMode) {
            createError({
                title: 'Error getting controller passport',
                body: `${error?.message}`,
                options: {
                    id: 'passport-fetch-error',
                },
            });
        }
    }, [error, isError, devMode]);

    return query;
};
