import { download } from '@gsm-common/utils/file/download';
import { createProgress } from '@gsm-common/utils/toast/createProgress';
import moment from 'moment';
import { useCallback, useEffect, useRef, useState } from 'react';
import { useSearchParams } from './useSearchParams';
import { useFullStory } from '@gsm-app/hooks/useFullStory';

const createVideoRecorder = (audio: HTMLAudioElement, video: HTMLVideoElement, options: MediaRecorderOptions) => {
    const videoStream = video.srcObject as MediaStream;
    const audioStream = audio.srcObject as MediaStream;
    const combinedStream = new MediaStream([...videoStream.getVideoTracks(), ...audioStream.getAudioTracks()]);
    const recorder = new MediaRecorder(combinedStream, options);
    return recorder;
};

const TimeStamp = () => {
    const [time, setTime] = useState(0);

    useEffect(() => {
        const interval = setInterval(() => setTime(prev => prev + 1000), 1000);
        return () => {
            clearInterval(interval);
        };
    }, []);

    return <>({moment.utc(time).format('HH:mm:ss')})</>;
};

export const useVideoCapture = (ref: HTMLElement | null) => {
    const recorderRef = useRef<MediaRecorder>();
    const [state, setState] = useState<RecordingState>('inactive');
    const { trackEvent } = useFullStory();
    const [{ gameId, channelName }] = useSearchParams<{
        gameId?: string;
        channelName?: string;
    }>();

    const handleStop = useCallback(() => {
        const r = recorderRef.current;
        if (r && r.state === 'recording') {
            setState(() => r.state);
            r.stop();
        }
    }, [recorderRef]);

    const handleCapture = useCallback(
        (maxVideoLengthMs: number = 300_000) => {
            const audio = ref?.getElementsByTagName('audio')[0];
            const video = ref?.getElementsByTagName('video')[0];

            if (!audio || !video) {
                return;
            }

            trackEvent('Record Game', {
                game: gameId,
                channel: channelName,
            });

            const chunks: Blob[] = [];
            const mimeType = 'video/webm;';
            const r = createVideoRecorder(audio, video, { mimeType });
            recorderRef.current = r;

            r.ondataavailable = e => chunks.push(e.data);
            r.start();
            setState(() => 'recording');

            // prevent the video from going beyond max length
            const lengthTimeout = setTimeout(handleStop, maxVideoLengthMs);

            const stopped = new Promise((resolve, reject) => {
                r.onstop = () => {
                    clearTimeout(lengthTimeout);
                    setState(() => r.state);
                    resolve(r.state);
                };
                r.onerror = event => {
                    clearTimeout(lengthTimeout);
                    setState(() => r.state);
                    reject(event);
                };
            });

            createProgress(
                stopped.then(() => {
                    const blob = new Blob(chunks, { type: mimeType });
                    download('video', blob, 'webm');
                }),
                {
                    title: {
                        loading: (
                            <div>
                                <b>Video Recording</b>
                                <TimeStamp />
                            </div>
                        ),
                        success: 'Video Record Complete',
                        error: 'Video Record Error',
                    },
                    options: {
                        id: 'video-capture',
                        position: 'top-center',
                    },
                },
            );
        },
        [recorderRef, ref, trackEvent, handleStop, gameId, channelName],
    );

    const handleToggle = useCallback(
        () => (state === 'inactive' ? handleCapture() : handleStop()),
        [state, handleCapture, handleStop],
    );

    return {
        state,
        stop: handleStop,
        capture: handleCapture,
        toggle: handleToggle,
    };
};
