import { useEnvVariables } from '@gsm-app/providers/EnvVariablesProvider';
import { yupResolver } from '@hookform/resolvers/yup';
import { EnvVarTable } from '@ncgt/common-ui';
import type { EnvVar } from '@ncgt/common/models/envVar';
import { forwardRef, useCallback, useImperativeHandle, useRef } from 'react';
import { FormProvider, type SubmitHandler, useFieldArray, useForm } from 'react-hook-form';
import type { FormState } from './models';
import { schema } from './schema';

export interface VariableFormRef {
    onSave: () => void;
    getVars: () => EnvVar[];
    replaceVars: (vars: EnvVar[]) => void;
}

interface VariableFormProps {
    loading?: boolean;
    disabled?: boolean;
    options: EnvVar[];
    onChangeOptions: (value: EnvVar[]) => void;
    gameId?: string;
    description?: React.ReactNode;
}

const createEmptyEnvVar = (): EnvVar => ({ key: '', value: '', enabled: true });

const normalizeEnabled = (vars: EnvVar[]): EnvVar[] =>
    vars.map((v) => ({ key: v.key, value: v.value, enabled: v.enabled !== false }));

export const VariableForm = forwardRef<VariableFormRef, VariableFormProps>(
    ({ disabled, options, onChangeOptions, gameId, description }, ref) => {
        const { setEnvVariables } = useEnvVariables();

        const methods = useForm<FormState>({
            mode: 'onChange',
            reValidateMode: 'onChange',
            resolver: yupResolver(schema) as never,
            defaultValues: {
                vars: options.length > 0 ? normalizeEnabled(options) : [createEmptyEnvVar()],
            },
        });

        const { fields, append, remove, update } = useFieldArray({
            control: methods.control,
            name: 'vars',
        });

        const handleSubmit: SubmitHandler<FormState> = useCallback(
            ({ vars }) => {
                const outgoing = normalizeEnabled(vars);
                onChangeOptions(outgoing);

                if (gameId) {
                    setEnvVariables(gameId, outgoing);
                }
            },
            [onChangeOptions, setEnvVariables, gameId],
        );

        const formRef = useRef<HTMLFormElement>(null);

        useImperativeHandle(
            ref,
            () => ({
                onSave() {
                    formRef.current?.dispatchEvent(new Event('submit', { cancelable: true, bubbles: true }));
                },
                getVars() {
                    return normalizeEnabled(methods.getValues('vars'));
                },
                replaceVars(newVars) {
                    const next = newVars.length > 0 ? normalizeEnabled(newVars) : [createEmptyEnvVar()];
                    methods.reset({ vars: next }, { keepDefaultValues: true });
                },
            }),
            [methods],
        );

        return (
            <FormProvider {...methods}>
                <form ref={formRef} id='variable-form' autoComplete='off' onSubmit={methods.handleSubmit(handleSubmit)}>
                    <EnvVarTable
                        fields={fields}
                        description={description}
                        disabled={disabled}
                        onAdd={() => append(createEmptyEnvVar())}
                        onRemove={(index) => remove(index)}
                        onToggleEnabled={(index, isEnabled) => {
                            const current = methods.getValues(`vars.${index}`);
                            update(index, { ...current, enabled: !isEnabled });
                        }}
                    />
                </form>
            </FormProvider>
        );
    },
);
