import { PlayerBlobContent } from '@gsm-app/components/PlayerBlobModal/components/PlayerBlobContent';
import { useAppQueryParams } from '@gsm-app/hooks/useAppQueryParams';
import { useNgpConfig } from '@gsm-app/hooks/useNgpConfig';
import { useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import {
    Button,
    ButtonGroup,
    Divider,
    Heading,
    Stack,
    Text,
    Toggle,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import type { EnvVar } from '@ncgt/common/models/envVar';
import { useEffect, useRef, useState } from 'react';
import { usePlayPage } from '../../PlayPageContext';
import { VariableForm, type VariableFormRef } from '../PageHeader/components/VariableForm';
import { type SessionSettingsContentRef, SessionSettingsContent } from '../SessionSettingsModal/SessionSettingsContent';
import type { SessionSettings } from '../SessionSettingsModal/SessionSettingsModal';
import styles from './SettingsPanel.module.css';

interface SettingsPanelProps {
    playing?: boolean;
    gameId: string;
    selectedEnvOptions: EnvVar[] | undefined;
    onSaveSettings: (settings: SessionSettings) => void;
    onSaveEnvVars: (value: EnvVar[]) => void;
    onClose?: () => void;
}

export const SettingsPanel = ({
    playing,
    gameId,
    selectedEnvOptions,
    onSaveSettings,
    onSaveEnvVars,
    onClose,
}: SettingsPanelProps) => {
    const { selectedAccount, isLoading } = useSopAccounts();
    const { gameId: queryGameId } = useAppQueryParams();
    const ngpConfig = useNgpConfig(gameId);
    const varFormRef = useRef<VariableFormRef>(null);
    const sessionSettingsRef = useRef<SessionSettingsContentRef>(null);
    const [activeTab, setActiveTab] = useState<'settings' | 'blobs' | 'envvars'>('settings');

    const { enforceEnvelope, onEnforceEnvelopeChange, enableScreenshots, onEnableScreenshotsChange } = usePlayPage();

    const [draftEnvelope, setDraftEnvelope] = useState(enforceEnvelope);
    const [draftScreenshots, setDraftScreenshots] = useState(enableScreenshots);

    // Sync draft state when context values change from outside (e.g. initial load)
    useEffect(() => {
        setDraftEnvelope(enforceEnvelope);
    }, [enforceEnvelope]);
    useEffect(() => {
        setDraftScreenshots(enableScreenshots);
    }, [enableScreenshots]);

    const handleSave = () => {
        sessionSettingsRef.current?.save();
        if (draftEnvelope !== enforceEnvelope) onEnforceEnvelopeChange(draftEnvelope);
        if (draftScreenshots !== enableScreenshots) onEnableScreenshotsChange(draftScreenshots);
        onClose?.();
    };

    const handleCancel = () => {
        setDraftEnvelope(enforceEnvelope);
        setDraftScreenshots(enableScreenshots);
        onClose?.();
    };

    return (
        <div className={styles.panel}>
            {/* ── Tab switcher ── */}
            <div className='sr-toolbar'>
                <div className='sr-toggle-flat'>
                    <ToggleButtonGroup
                        compact
                        exclusive
                        value={activeTab}
                        onChange={(_ev, value) => {
                            if (value) setActiveTab(value as typeof activeTab);
                        }}
                    >
                        <ToggleButton value='settings'>Settings</ToggleButton>
                        <ToggleButton value='blobs'>Player Blobs</ToggleButton>
                        <ToggleButton value='envvars'>Env Variables</ToggleButton>
                    </ToggleButtonGroup>
                </div>
            </div>

            {/* ── Settings content ── */}
            {activeTab === 'settings' && (
                <>
                    <div className={styles.tabContent}>
                        <section className={styles.section}>
                            <Heading level={2} className={styles.sectionTitle}>
                                OCG Settings
                            </Heading>
                            <SessionSettingsContent
                                ref={sessionSettingsRef}
                                isActive
                                playing={playing}
                                gameId={gameId}
                                ngpConfig={ngpConfig.data}
                                onSave={onSaveSettings}
                                showFooter={false}
                            />
                        </section>

                        <Divider style={{ margin: `${Dimensions.Space12} 0` }} />

                        <section className={styles.section}>
                            <Heading level={2} className={styles.sectionTitle}>
                                Performance Graph Settings
                            </Heading>
                            <Stack gap={Dimensions.Space12} orientation='vertical'>
                                <Tooltip label='Show resource usage bands and alert when metrics exceed limits. Can only be changed when no session is active.'>
                                    <Toggle
                                        checked={draftEnvelope}
                                        label='Enforce Resource Envelope'
                                        name='settings-panel-enforce-envelope'
                                        disabled={playing}
                                        onChange={(_e, checked) => setDraftEnvelope(checked)}
                                    />
                                </Tooltip>
                                <Tooltip label='Automatically capture screenshots from the game stream at regular intervals. Can only be changed when no session is active.'>
                                    <Toggle
                                        checked={draftScreenshots}
                                        label='Enable Screenshots'
                                        name='settings-panel-enable-screenshots'
                                        disabled={playing}
                                        onChange={(_e, checked) => setDraftScreenshots(checked)}
                                    />
                                </Tooltip>
                                {playing && (
                                    <Text colorVariant='faded' style={{ fontSize: '12px' }}>
                                        Cannot change during an active session.
                                    </Text>
                                )}
                            </Stack>
                        </section>
                    </div>

                    <div className={styles.footer}>
                        <ButtonGroup justifyContent='flex-end'>
                            <Button variant='secondary' onClick={handleCancel} disabled={playing}>
                                Cancel
                            </Button>
                            <Button variant='primary' onClick={handleSave} disabled={playing}>
                                Save
                            </Button>
                        </ButtonGroup>
                    </div>
                </>
            )}

            {/* ── Player Blobs content ── */}
            {activeTab === 'blobs' && (
                <div className={styles.tabContent}>
                    <Text colorVariant='faded' level={0} variant='label'>
                        Test Account
                    </Text>
                    <Text style={{ marginBottom: Dimensions.Space10 }}>{selectedAccount?.value ?? '—'}</Text>
                    <PlayerBlobContent
                        gameId={queryGameId}
                        email={selectedAccount?.value}
                        loadingSopAccount={isLoading}
                    />
                </div>
            )}

            {/* ── Env Variables content ── */}
            {activeTab === 'envvars' && (
                <div className={styles.tabContent}>
                    <section className={styles.section}>
                        <Heading level={2} className={styles.sectionTitle}>
                            Environment Variables
                        </Heading>
                        <Text variant='body' colorVariant='faded' style={{ marginBottom: Dimensions.Space8 }}>
                            {playing
                                ? 'Environment variables cannot be modified during play'
                                : 'Environment variables are sent at the start of a game'}
                        </Text>
                        <VariableForm
                            ref={varFormRef}
                            disabled={playing}
                            options={selectedEnvOptions ?? []}
                            onChangeOptions={onSaveEnvVars}
                            gameId={gameId}
                        />
                    </section>
                </div>
            )}
        </div>
    );
};
