const ITERATIONS = 10;
const ENCRYPT_ALGO = 'AES-GCM';
const IV_LENGTH = 12;
const SALT_LENGTH = 16;
const DIGEST_ALGO = 'SHA-256';

const getDerivedKey = async (secret: string, salt: Uint8Array) => {
    const key = await window.crypto.subtle.importKey('raw', new TextEncoder().encode(secret), 'PBKDF2', false, [
        'deriveKey',
    ]);
    return window.crypto.subtle.deriveKey(
        {
            name: 'PBKDF2',
            salt,
            iterations: ITERATIONS,
            hash: DIGEST_ALGO,
        },
        key,
        {
            name: ENCRYPT_ALGO,
            length: 256,
        },
        false,
        ['encrypt', 'decrypt'],
    );
};

export const encrypt = async (secret: string, data: string) => {
    try {
        const salt = window.crypto.getRandomValues(new Uint8Array(SALT_LENGTH));
        const iv = window.crypto.getRandomValues(new Uint8Array(IV_LENGTH));
        const key = await getDerivedKey(secret, salt);
        const encodedData = new TextEncoder().encode(data);
        const encryptedData = await window.crypto.subtle.encrypt(
            {
                name: ENCRYPT_ALGO,
                iv,
            },
            key,
            encodedData,
        );
        const encryptedBuff: Uint8Array = new Uint8Array(encryptedData);
        const buff: Uint8Array = new Uint8Array(salt.byteLength + iv.byteLength + encryptedBuff.byteLength);
        buff.set(salt, 0);
        buff.set(iv, salt.byteLength);
        buff.set(encryptedBuff, salt.byteLength + iv.byteLength);
        return btoa(String.fromCharCode.apply(undefined, [...buff]));
    } catch (error) {
        console.error(`Encryption Error: ${error}`);
        return '';
    }
};

export const decrypt = async (secret: string, data: string) => {
    try {
        const dataBuffer = Uint8Array.from(atob(data), c => c.charCodeAt(0));
        const salt = dataBuffer.slice(0, SALT_LENGTH);
        const iv = dataBuffer.slice(SALT_LENGTH, SALT_LENGTH + IV_LENGTH);
        const encryptedData = dataBuffer.slice(SALT_LENGTH + IV_LENGTH);
        const key = await getDerivedKey(secret, salt);
        const decryptedData = await window.crypto.subtle.decrypt(
            {
                name: ENCRYPT_ALGO,
                iv,
            },
            key,
            encryptedData,
        );
        return new TextDecoder().decode(decryptedData);
    } catch (error) {
        console.error(`Decryption Error: ${error}`);
        return '';
    }
};
