import type { useControllerLogs } from '@gsm-app/hooks/useControllerLogs';
import type { ControllerOption } from '@gsm-app/hooks/useGameControllers';
import type { useSessionGameLogs } from '@gsm-app/hooks/useSessionGameLogs';
import type { ControllerEnvironment, SsicWindowConfig } from '@gsm-app/hooks/useSsicWindow';
import type { Build } from '@gsm-app/models/Build';
import type { StreamingMode } from '@gsm-app/models/StreamingMode';
import type { Screenshot, ScreenshotQuality } from '@gsm-common/hooks/usePeriodicScreenshots';
export type { Screenshot, ScreenshotQuality };
import type { PerformanceSummary } from '@gsm-app/components/SessionSummaryBanner/generatePerformanceSummary';
import type { DropdownOption } from '@hawkins/components';
import type { EnvVar } from '@ncgt/common/models/envVar';
import type { LoadingProgress } from '@ncgt/player';
import { type MouseEvent, createContext, useContext } from 'react';
import type { SessionSettings } from './components/SessionSettingsModal/SessionSettingsModal';

/** A single point in time shared between the live perf graph and the logs panel (separate
 * Dockview panels, connected only via this context), tagged with which side last set it so
 * each side can ignore updates it caused itself. */
export type Playhead = { time: number; source: 'graph' | 'log' } | null;

export type PlayPageContextValue = {
    sessionId: string | undefined;
    mode: StreamingMode;
    activeBuild: Build | null | undefined;
    isLoading: boolean;
    isDisconnected: boolean;
    failedMessage: string | undefined;
    loadingProgress: LoadingProgress | undefined;
    toggleConnection: (e: MouseEvent<HTMLButtonElement>) => void;
    selectedGame: DropdownOption<string> | undefined;
    selectedChannel: DropdownOption<string> | undefined;
    qrCodeUrl: string | undefined;
    passport: string | undefined;
    showSSIC: boolean;
    setShowSSIC: (v: boolean) => void;
    controllerEnv: ControllerEnvironment;
    setControllerEnv: (v: ControllerEnvironment) => void;
    ssicWindowConfig: SsicWindowConfig;
    setSsicWindowConfig: (v: SsicWindowConfig) => void;
    sideloadedControllerUrl: string | undefined;
    controllerOptions: ControllerOption[];
    selectedController: string | undefined;
    setSelectedController: (id: string | undefined) => void;
    testbedVersion: string;
    setTestbedVersion: (v: string) => void;
    selectedEnvOptions: EnvVar[] | undefined;
    setSessionSettings: (settings: SessionSettings) => void;
    setSelectedEnvOptions: (vars: EnvVar[]) => void;
    screenshots: Screenshot[];
    enableScreenshots: boolean;
    captureIntervalMs: number;
    screenshotQuality: ScreenshotQuality;
    onEnableScreenshotsChange: (enabled: boolean) => void;
    onCaptureIntervalChange: (intervalMs: number) => void;
    onScreenshotQualityChange: (quality: ScreenshotQuality) => void;
    enforceEnvelope: boolean;
    onEnforceEnvelopeChange: (v: boolean) => void;
    resourceDisplayMode: 'percent' | 'both';
    onResourceDisplayModeChange: (mode: 'percent' | 'both') => void;
    resourceLimits: { cpu: number; gpu: number; ram: number; vram: number };
    onResourceLimitsChange: (limits: { cpu: number; gpu: number; ram: number; vram: number }) => void;
    performanceSummary: PerformanceSummary | null;
    setPerformanceSummary: (summary: PerformanceSummary | null) => void;
    /** Lifted here (rather than fetched separately per panel) so the logs panel and the
     * performance graph's error/warning markers share a single telemetry subscription. */
    gameLogs: ReturnType<typeof useSessionGameLogs>;
    controllerLogs: ReturnType<typeof useControllerLogs>;
    /** Shared playhead between the perf graph and logs panels (bidirectional click-sync). */
    playhead: Playhead;
    onGraphPlayhead: (seconds: number) => void;
    onLogPlayhead: (seconds: number) => void;
    /** Approximate epoch ms for t=0 (session start) — only used to keep displayed durations
     * ("00:23") small/sane on both sides; sync correctness doesn't depend on its exact value. */
    sessionStartMs: number;
};

const PlayPageContext = createContext<PlayPageContextValue | null>(null);

export const PlayPageProvider = PlayPageContext.Provider;

export function usePlayPage(): PlayPageContextValue {
    const ctx = useContext(PlayPageContext);
    if (!ctx) throw new Error('usePlayPage must be used within PlayPageProvider');
    return ctx;
}
