import { useFeature } from '@gsm-app/hooks/useFeature';
import { useFullStory } from '@gsm-app/hooks/useFullStory';
import type { ControllerOption } from '@gsm-app/hooks/useGameControllers';
import { ControllerEnvironment, type SsicWindowConfig } from '@gsm-app/hooks/useSsicWindow';
import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useStreamingModeInfo } from '@gsm-app/routes/Play/hooks/useStreamingModeInfo';
import { buildControllerUrl, extractBeaconCode } from '@gsm-app/utils/buildControllerUrl';
import { createToast } from '@gsm-common/utils/toast/createToast';
import { createWarning } from '@gsm-common/utils/toast/createWarning';
import { IconClipboard, IconCollapsePanelLeft, IconLinkOut } from '@hawkins/assets';
import {
    Button,
    ContextualBanner,
    HawkinsProvider,
    Input,
    SkeletonLoader,
    Stack,
    Text,
    ToggleButton,
    ToggleButtonGroup,
    Tooltip,
} from '@hawkins/components';
import type { ToggleButtonValue } from '@hawkins/components/lib/toggleButtonGroup/toggleButtonGroup.context';
import { Colors, Dimensions } from '@hawkins/variables';
import { useControllerBeacon } from '@ncgt/player';
import { QRCodeSVG } from 'qrcode.react';
import { useCallback, useMemo } from 'react';
import styles from './SSICQrCode.module.css';

interface SSICQrCodeProps {
    mode: StreamingMode;
    qrCodeUrl: string | undefined;
    passport: string | undefined;
    showSSIC: boolean;
    setShowSSIC: (showSSIC: boolean) => void;
    controllerEnv: ControllerEnvironment;
    setControllerEnv: (env: ControllerEnvironment) => void;
    ssicWindowConfig: SsicWindowConfig;
    setSsicWindowConfig: (ssicWindowConfig: SsicWindowConfig) => void;
    controllerOptions: ControllerOption[];
    selectedController: string | undefined;
    setSelectedController: (value: string | undefined) => any;
    sideloadedControllerUrl?: string;
    testbedVersion: string;
    setTestbedVersion: (v: string) => void;
    onCollapse?: () => void;
    collapseIcon?: typeof IconCollapsePanelLeft;
    hideToolbar?: boolean;
}

// QR code size fitted for the 210px panel (allows for border + padding)
const QRCodeSizePanel = 170;

function createSegments(url: string): string[] {
    try {
        const { origin } = new URL(url);
        const segments = [origin, url.slice(origin.length)];
        if (segments.join('') === url) {
            return segments;
        }
        return [url];
    } catch (_e) {
        return [url];
    }
}

export function SSICQrCode(props: SSICQrCodeProps) {
    const {
        mode,
        qrCodeUrl,
        passport,
        showSSIC,
        setShowSSIC,
        ssicWindowConfig,
        setSsicWindowConfig,
        controllerEnv,
        setControllerEnv,
        sideloadedControllerUrl,
        selectedController: _selectedController,
        setSelectedController: _setSelectedController,
        controllerOptions: _controllerOptions,
        testbedVersion,
        setTestbedVersion,
        onCollapse,
        collapseIcon: CollapseIcon = IconCollapsePanelLeft,
        hideToolbar = false,
    } = props;

    const { controllerBeacon, controllerConnectToEditorLink, enableLoadCustomTestbedVersion } = useFeature();
    const { isDisconnected } = useStreamingModeInfo(mode);
    const [redeemBeacon] = useControllerBeacon({ passport: passport ?? '' });
    const { trackEvent } = useFullStory();

    const segmentedUrl = useMemo(() => (qrCodeUrl ? createSegments(qrCodeUrl) : qrCodeUrl), [qrCodeUrl]);
    const devMode = process.env.NODE_ENV === 'development';
    const stagingStack = useMemo(() => window.location.href.includes('staging'), []);
    const sessionOpen = mode === StreamingMode.OPEN;

    const handleCopyQrCode = useCallback(() => {
        if (!qrCodeUrl) return;
        try {
            navigator.clipboard.writeText(qrCodeUrl);
            createToast({ title: 'Link copied to clipboard', icon: IconClipboard });
        } catch (_e) {
            createWarning({ title: 'Link copy failed', icon: IconClipboard });
        }
    }, [qrCodeUrl]);

    const handleChangeControllerEnvironment = useCallback(
        (_ev: React.MouseEvent<HTMLElement>, newValue: ToggleButtonValue | ToggleButtonValue[]) => {
            setControllerEnv(newValue as ControllerEnvironment);
            trackEvent('Controller Env', { env: newValue });
        },
        [trackEvent, setControllerEnv],
    );

    const tooltipProps = useMemo(() => {
        if (sideloadedControllerUrl) {
            return {
                [ControllerEnvironment.TESTBED]: {
                    tooltipDescription: '',
                    tooltipLabel: 'Controller environment not available for builds with sideloaded controller url',
                },
                [ControllerEnvironment.PROD]: {
                    tooltipDescription: '',
                    tooltipLabel: 'Controller environment not available for builds with sideloaded controller url',
                },
            };
        }
        if (isDisconnected) {
            return {
                [ControllerEnvironment.TESTBED]: {
                    tooltipDescription: 'Includes unreleased features still in development.',
                    tooltipLabel: 'Simulate test environment',
                },
                [ControllerEnvironment.PROD]: {
                    tooltipDescription: 'Includes only fully released features.',
                    tooltipLabel: 'Simulate production environment',
                },
            };
        }
        return {
            [ControllerEnvironment.TESTBED]: {
                tooltipDescription: '',
                tooltipLabel: 'Cannot edit while the game is running',
            },
            [ControllerEnvironment.PROD]: {
                tooltipDescription: '',
                tooltipLabel: 'Cannot edit while the game is running',
            },
        };
    }, [isDisconnected, sideloadedControllerUrl]);

    const handleConnectToControllerEditor = useCallback(async () => {
        if (!qrCodeUrl || !passport) return;
        const beaconCode = extractBeaconCode(qrCodeUrl);
        if (!beaconCode) return;
        try {
            const result = await redeemBeacon({ variables: { beaconCode } });
            const redeemed = result.data?.ngpRedeemBeacon;
            if (redeemed?.__typename === 'NGPRedeemBeaconFailed') {
                createWarning({ title: redeemed.reason || 'Could not connect to Controller Editor' });
                return;
            }
            if (!redeemed || redeemed.__typename !== 'NGPRedeemBeaconSuccess') return;
            window.open(buildControllerUrl(redeemed).replace(/^https?:\/\//, 'ngce://'));
        } catch (_e) {
            createWarning({ title: 'Could not connect to Controller Editor' });
        }
    }, [qrCodeUrl, passport, redeemBeacon]);

    return (
        <div className={styles.panel}>
            {/* ── Header ── */}
            {!hideToolbar && (
                <div className='sr-toolbar'>
                    <Button
                        compact
                        variant='icon'
                        icon={CollapseIcon}
                        aria-label='Collapse panel'
                        onClick={onCollapse}
                    />
                    <span className={styles.panelTitle}>NGC QR Code</span>
                    <Button
                        compact
                        variant='icon'
                        icon={IconLinkOut}
                        aria-label='Open QR code in new tab'
                        disabled={!sessionOpen || !qrCodeUrl}
                        onClick={() => qrCodeUrl && window.open(qrCodeUrl, '_blank')}
                    />
                </div>
            )}

            {/* ── Controls ── */}
            <div className={styles.panelContent}>
                {/* Dev-mode warning */}
                {devMode && controllerBeacon && !stagingStack && (
                    <ContextualBanner
                        compact
                        text='Run in `production` environment to test controller flow'
                        variant='warning'
                    />
                )}

                {/* Controller environment toggle */}
                {controllerBeacon && (
                    <ToggleButtonGroup
                        compact
                        disabled={!isDisconnected || Boolean(sideloadedControllerUrl)}
                        onChange={handleChangeControllerEnvironment}
                        defaultValue={controllerEnv}
                        style={{ width: '100%' }}
                    >
                        <ToggleButton
                            compact
                            value={ControllerEnvironment.TESTBED}
                            tooltipDescription={tooltipProps[ControllerEnvironment.TESTBED].tooltipDescription}
                            tooltipLabel={tooltipProps[ControllerEnvironment.TESTBED].tooltipLabel}
                        >
                            Testbed
                        </ToggleButton>
                        <ToggleButton
                            compact
                            value={ControllerEnvironment.PROD}
                            tooltipDescription={tooltipProps[ControllerEnvironment.PROD].tooltipDescription}
                            tooltipLabel={tooltipProps[ControllerEnvironment.PROD].tooltipLabel}
                        >
                            Prod
                        </ToggleButton>
                    </ToggleButtonGroup>
                )}

                {/* Testbed version input */}
                {enableLoadCustomTestbedVersion &&
                    controllerEnv === ControllerEnvironment.TESTBED &&
                    !sideloadedControllerUrl && (
                        <Tooltip
                            placement='top'
                            label="Specify a testbed version to load. Leave blank or enter 'latest' to use the most recent testbed version."
                        >
                            <Input
                                compact
                                label='Testbed version'
                                value={testbedVersion}
                                onChange={(e) => setTestbedVersion(e.target.value)}
                                disabled={!isDisconnected}
                                inputProps={{ autoComplete: 'off', placeholder: 'latest' }}
                                style={{ width: '100%' }}
                            />
                        </Tooltip>
                    )}

                {/* Starting Players + Max Players side by side */}
                <div className={styles.inputRow}>
                    <Input
                        compact
                        label='Starting Players'
                        onChange={(e) => {
                            if (Number.isInteger(+e.target.value)) {
                                setSsicWindowConfig({ ...ssicWindowConfig, minSSIC: +e.target.value });
                            }
                        }}
                        value={ssicWindowConfig.minSSIC}
                        disabled={showSSIC}
                        inputProps={{ pattern: /^[0-9]+$/, autoComplete: 'off' }}
                    />
                    <Input
                        compact
                        label='Max Players'
                        onChange={(e) => {
                            if (Number.isInteger(+e.target.value)) {
                                setSsicWindowConfig({ ...ssicWindowConfig, maxSSIC: +e.target.value });
                            }
                        }}
                        value={ssicWindowConfig.maxSSIC}
                        disabled={showSSIC}
                        inputProps={{ pattern: /^[0-9]+$/, autoComplete: 'off' }}
                    />
                </div>

                {/* Open / Close Virtual Controller */}
                <Button
                    compact
                    variant='secondary'
                    style={{ width: '100%' }}
                    disabled={!sessionOpen}
                    onClick={() => setShowSSIC(!showSSIC)}
                >
                    {showSSIC ? 'Close Virtual Controller' : 'Open Virtual Controller'}
                </Button>

                {/* Connect to Controller Editor */}
                {controllerConnectToEditorLink && (
                    <Button
                        compact
                        variant='secondary'
                        style={{ width: '100%' }}
                        disabled={!sessionOpen || !qrCodeUrl || !passport}
                        onClick={handleConnectToControllerEditor}
                    >
                        Connect to Controller Editor
                    </Button>
                )}
            </div>

            {/* ── QR code (bottom) ── */}
            <div className={styles.panelQr}>
                {sessionOpen ? (
                    <HawkinsProvider theme='dark'>
                        {controllerBeacon ? (
                            <div className={styles.qrCode}>
                                {segmentedUrl ? (
                                    <QRCodeSVG
                                        level='L'
                                        size={QRCodeSizePanel}
                                        value={segmentedUrl}
                                        bgColor='transparent'
                                        fgColor={Colors.Black}
                                        boostLevel={false}
                                        data-url={qrCodeUrl}
                                    />
                                ) : (
                                    <SkeletonLoader variant='square' width={QRCodeSizePanel} height={QRCodeSizePanel} />
                                )}
                            </div>
                        ) : (
                            <Stack gap={Dimensions.Space8} layout={{ alignItems: 'center' }}>
                                <div className={styles.qrCode}>
                                    {qrCodeUrl ? (
                                        <QRCodeSVG
                                            level='L'
                                            size={QRCodeSizePanel}
                                            value={qrCodeUrl}
                                            bgColor='transparent'
                                            fgColor={Colors.Black}
                                            boostLevel={false}
                                            data-url={qrCodeUrl}
                                        />
                                    ) : (
                                        <SkeletonLoader
                                            variant='square'
                                            width={QRCodeSizePanel}
                                            height={QRCodeSizePanel}
                                        />
                                    )}
                                </div>
                                {qrCodeUrl && (
                                    <Button compact icon={IconClipboard} variant='tertiary' onClick={handleCopyQrCode}>
                                        Copy Link
                                    </Button>
                                )}
                            </Stack>
                        )}
                    </HawkinsProvider>
                ) : (
                    <ContextualBanner compact text='Start a session to get a Controller QR code' />
                )}
            </div>
        </div>
    );
}
