import { useEffect, useRef, useState } from 'react';

export interface SsicWindowConfig {
    minSSIC: number;
    maxSSIC: number;
}

interface SsicWindowProps {
    qrCodeUrl: string | undefined;
    config: SsicWindowConfig;
    passport?: string;
}

export enum ControllerEnvironment {
    TESTBED = 'TESTBED',
    PROD = 'PROD',
    DEFAULT = 'DEFAULT',
}
export const CONTROLLER_ENV_STORAGE_KEY = 'ncgt_ssicEnv';
export const TESTBED_VERSION_STORAGE_KEY = 'ncgt_ssicTestbedVersion';

export const TESTBED_VERSION_LATEST = 'latest';

export const useSsicWindow = ({ qrCodeUrl, config, passport = '' }: SsicWindowProps) => {
    const [showSSIC, setShowSSIC] = useState<boolean>(false);

    const [controllerEnv, setControllerEnv] = useState<ControllerEnvironment>(ControllerEnvironment.PROD);
    const [testbedVersion, setTestbedVersion] = useState<string>(TESTBED_VERSION_LATEST);
    const ssicWindow = useRef<Window | null>(null);

    useEffect(() => {
        const controllerEnvironmentStoredValue = localStorage.getItem(CONTROLLER_ENV_STORAGE_KEY);
        if (controllerEnvironmentStoredValue === ControllerEnvironment.TESTBED) {
            setControllerEnv(controllerEnvironmentStoredValue);
        }

        const storedVersion = localStorage.getItem(TESTBED_VERSION_STORAGE_KEY);
        if (storedVersion) {
            setTestbedVersion(storedVersion);
        }
    }, []);

    useEffect(() => {
        if (controllerEnv === ControllerEnvironment.TESTBED) {
            localStorage.setItem(CONTROLLER_ENV_STORAGE_KEY, ControllerEnvironment.TESTBED);
            if (testbedVersion) {
                localStorage.setItem(TESTBED_VERSION_STORAGE_KEY, testbedVersion);
            }
        } else {
            localStorage.removeItem(CONTROLLER_ENV_STORAGE_KEY);
        }
    }, [controllerEnv, testbedVersion]);

    useEffect(() => {
        let ssicClosedTimer: number;
        if (showSSIC && !ssicWindow.current) {
            const url = `/ssic?url=${encodeURIComponent(qrCodeUrl ?? '')}&min=${config.minSSIC}&max=${config.maxSSIC}&passport=${passport}&beacon=true`;

            ssicWindow.current = window.open(
                url,
                'Portal - Virtual Controller',
                'width=1000,height=600,left=800,top=200,popup',
            );

            ssicClosedTimer = window.setInterval(() => {
                if (ssicWindow.current?.closed) {
                    window.clearInterval(ssicClosedTimer);
                    setShowSSIC(false);
                }
            }, 300);
        } else if (!showSSIC && ssicWindow.current) {
            ssicWindow.current.close();
            ssicWindow.current = null;
        }
        return () => window.clearInterval(ssicClosedTimer);
    }, [
        showSSIC,
        qrCodeUrl,
        config.maxSSIC,
        config.minSSIC,
        passport,
    ]);

    useEffect(() => {
        const closeSSIC = () => {
            setShowSSIC(false);
        };
        window.addEventListener('beforeunload', closeSSIC);
        return () => window.removeEventListener('beforeunload', closeSSIC);
    }, []);

    return {
        showSSIC,
        setShowSSIC,
        controllerEnv,
        setControllerEnv,
        testbedVersion,
        setTestbedVersion,
    };
};
