import { Text, type TextProps } from '@hawkins/components';

export interface SkeletonTextProps {
    label: string;
    labelProps?: TextProps;
    value: string | number | undefined;
    width?: string | number;
    color?: string;
}
export const SkeletonText = ({ label, labelProps, value, width, color }: SkeletonTextProps) => {
    const loading = value === undefined;
    return (
        <>
            <Text {...labelProps}>{label}</Text>
            &nbsp;
            <Text
                color={color}
                loading={loading}
                loaderProps={{
                    width,
                }}
            >
                {value}
            </Text>
        </>
    );
};
