import { useMemo } from 'react';

const UNIQUE_CLIENT_ID_KEY = 'uniqueClientId';

export const useUniqueClientId = () => {
    return useMemo<string>(() => {
        let savedClientId = localStorage.getItem(UNIQUE_CLIENT_ID_KEY);
        if (!savedClientId) {
            savedClientId = (Math.random() + 1).toString(36).substring(2).toUpperCase();
            localStorage.setItem(UNIQUE_CLIENT_ID_KEY, savedClientId);
        }
        return savedClientId;
    }, []);
};
