import { fetch } from '@gsm-app/utils/fetch';
import { createError } from '@gsm-common/utils/toast/createError';
import type { DropdownOption } from '@hawkins/components';
import { useQuery } from '@tanstack/react-query';
import { useEffect, useMemo, useState } from 'react';

export interface Controller {
    id: string;
    config: string;
    url: string;
    orientations: string[];
    name: string;
}

export interface ControllersResponse {
    data: {
        alternateControllers: Controller[] | null;
        defaultController: Controller | null;
        sideloadedControllerUrl?: string;
    };
}

export interface ControllerOption extends DropdownOption<string> {
    default: boolean;
    url?: string;
    config: string;
}

const formatControllerOptions = (data: ControllersResponse['data']): ControllerOption[] => {
    if (!data) {
        createError({
            title: 'Missing controller config',
            body: 'No controller configuration found for the build',
            options: {
                id: 'build-missing-controller-config',
            },
        });
        return [];
    }

    const options = [data.defaultController, ...(data?.alternateControllers ?? [])].filter((controller) =>
        Boolean(controller),
    ) as Controller[];
    return options.map((controller, i) => {
        return {
            value: controller.id,
            label: controller.name,
            default: i === 0,
            config: controller.config,
        };
    });
};

export const useGameControllers = (gameId: string | undefined, buildKey: string | undefined) => {
    const [selectedController, setSelectedController] = useState<string>();
    const { data, isLoading } = useQuery<ControllersResponse>({
        enabled: Boolean(gameId) && Boolean(buildKey),
        queryKey: ['game_controllers', gameId, buildKey],
        queryFn: async ({ signal }) => {
            return fetch(`/api/games/${gameId}/builds/${buildKey}/controllers`, { signal }).then((res) => res.json());
        },
    });

    const controllerOptions = useMemo<ControllerOption[]>(
        () => (data?.data ? formatControllerOptions(data.data) : []),
        [data?.data],
    );

    const sideloadedControllerUrl = useMemo(() => {
        return data?.data.sideloadedControllerUrl;
    }, [data?.data]);

    useEffect(() => {
        // set no controller when loading
        if (isLoading) {
            setSelectedController(() => undefined);
            return;
        }
        // set default controller when data changes
        if (controllerOptions) {
            const controller = controllerOptions.find((c) => c.default);
            setSelectedController(() => controller?.value);
            return;
        }
    }, [controllerOptions, isLoading]);

    return {
        controllerOptions,
        isLoading,
        sideloadedControllerUrl,
        selectedController,
        setSelectedController,
    };
};
