import { decrypt } from '@gsm-app/utils/encrypt';
import type { DropdownOption } from '@hawkins/components';
import type { EnvVar } from '@ncgt/common/models/envVar';
import { mapSavedEnvVarsToModel } from '@ncgt/common/utils/envVar';
import { useCallback, useEffect, useMemo, useState } from 'react';
import { useSecretKey } from './useSecretKey';

interface EnvOptionProps {
    selectedGame: DropdownOption<string> | undefined;
}

const ENV_OPTIONS_KEY = 'ncgt_envOptions';

export const useEnvOptions = ({ selectedGame }: EnvOptionProps) => {
    const [allEnvOptions, setAllEnvOptions] = useState<{ [gameId: string]: EnvVar[] }>(() => {
        try {
            const raw = localStorage.getItem(ENV_OPTIONS_KEY);
            return raw ? mapSavedEnvVarsToModel(JSON.parse(raw)) : {};
        } catch {
            return {};
        }
    });

    const selectedEnvOptions = useMemo<EnvVar[]>(() => {
        if (!selectedGame) return [];
        return allEnvOptions[selectedGame.value] ?? [];
    }, [allEnvOptions, selectedGame]);

    const setSelectedEnvOptions = useCallback(
        (newEnvOptions: EnvVar[]) => {
            if (selectedGame) {
                setAllEnvOptions((prev) => {
                    const newValue = { ...prev, [selectedGame.value]: newEnvOptions };
                    localStorage.setItem(ENV_OPTIONS_KEY, JSON.stringify(newValue));
                    return newValue;
                });
            }
        },
        [selectedGame],
    );

    const queryParams = new URLSearchParams(window.location.search);
    const encryptedEnvOptions = queryParams.get('encryptedEnvVariables');
    if (encryptedEnvOptions) {
        const { secretKey } = useSecretKey();
        useEffect(() => {
            if (!secretKey) return;
            const load = async () => {
                try {
                    const decryptedEnvOptions = await decrypt(secretKey, encryptedEnvOptions);
                    const envOptions = JSON.parse(decryptedEnvOptions);
                    const transformed: EnvVar[] = Array.isArray(envOptions)
                        ? envOptions.map((option: EnvVar) => ({
                              key: String(option.key ?? ''),
                              value: String(option.value ?? ''),
                              enabled: option.enabled !== false,
                          }))
                        : [];
                    setSelectedEnvOptions(transformed);
                } catch (e) {
                    console.error('Failed to decrypt env options from URL:', e);
                }
            };
            load();
        }, [secretKey, encryptedEnvOptions, setSelectedEnvOptions]);
    }

    return {
        selectedEnvOptions,
        setSelectedEnvOptions,
    };
};
