import { createProgress } from '@gsm-common/utils/toast/createProgress';
import { useCallback } from 'react';
import { useSearchParams } from './useSearchParams';
import { useFullStory } from '@gsm-app/hooks/useFullStory';

const isHTMLVideoElement = (obj: any): obj is HTMLVideoElement => {
    return obj && typeof obj.videoWidth === 'number';
};

const imageBlob = (source: ImageBitmap | HTMLVideoElement) => {
    return new Promise<Blob>((resolve, reject) => {
        const canvas = document.createElement('canvas');
        const ctx = canvas.getContext('2d');
        if (ctx) {
            if (isHTMLVideoElement(source)) {
                canvas.width = source.videoWidth;
                canvas.height = source.videoHeight;
            } else {
                canvas.width = source.width;
                canvas.height = source.height;
            }

            ctx.drawImage(source, 0, 0, canvas.width, canvas.height);
        }

        canvas.toBlob(blob => (blob ? resolve(blob) : reject()));
    });
};

const copyToClipboard = (blob: Blob) => {
    return new Promise(async (resolve, reject) => {
        if (!blob) {
            return reject();
        }
        try {
            const item = new ClipboardItem({ 'image/png': blob });
            return resolve(await navigator.clipboard.write([item]));
        } catch (e: any) {
            return reject(e);
        }
    });
};

const mediaStreamBlob = async (stream: MediaStream) => {
    const videoTrack = stream.getVideoTracks()[0];

    if (!videoTrack) {
        return Promise.reject();
    }

    // ImageCapture when supported
    if ('ImageCapture' in window) {
        const imageCapture = new ImageCapture(videoTrack);
        const image = await imageCapture.grabFrame();
        // NOTE: imageCapture.takePhoto not supported
        return imageBlob(image);
    }

    // fallback to using the video element to create blob
    return new Promise<Blob>((resolve, reject) => {
        const video = document.createElement('video');
        video.srcObject = stream;
        video.muted = true;
        video
            .play()
            .then(() => {
                resolve(imageBlob(video));
            })
            .catch(reject);
    });
};

export const useScreenshot = (ref: HTMLElement | null) => {
    const [{ gameId, channelName }] = useSearchParams<{
        gameId?: string;
        channelName?: string;
    }>();

    const { trackEvent } = useFullStory();

    const handleCapture = useCallback(() => {
        const video = ref?.getElementsByTagName('video')[0];

        if (!video) {
            return;
        }

        trackEvent('Screenshot Game', {
            game: gameId,
            channel: channelName,
        });

        const videoStream = video.srcObject as MediaStream;

        createProgress(mediaStreamBlob(videoStream).then(copyToClipboard), {
            title: {
                loading: <b>Creating Screenshot...</b>,
                success: <b>Screenshot copied to clipboard</b>,
                error: <b>Failed to copy screenshot!</b>,
            },
            options: {
                id: 'screenshot',
                position: 'top-center',
            },
        });
    }, [ref, gameId, channelName]);

    return {
        capture: handleCapture,
    };
};
