import type { PerformanceSummary } from '@gsm-app/components/SessionSummaryBanner/generatePerformanceSummary';
import { useControllerLogs } from '@gsm-app/hooks/useControllerLogs';
import { useEnvOptions } from '@gsm-app/hooks/useEnvOptions';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { useGameControllers } from '@gsm-app/hooks/useGameControllers';
import { useSessionGameLogs } from '@gsm-app/hooks/useSessionGameLogs';
import { useSessionSettings } from '@gsm-app/hooks/useSessionSettings';
import { type SsicWindowConfig, TESTBED_VERSION_LATEST, useSsicWindow } from '@gsm-app/hooks/useSsicWindow';
import { useUniqueClientId } from '@gsm-app/hooks/useUniqueClientId';
import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useSopAccounts } from '@gsm-app/providers/SopAccountProvider';
import { Content } from '@gsm-common/components/Content';
import { Layout } from '@gsm-common/components/Layout';
import { usePassport } from '@gsm-common/hooks/usePassport';
import {
    DEFAULT_CAPTURE_INTERVAL_MS,
    DEFAULT_SCREENSHOT_QUALITY,
    usePeriodicScreenshots,
} from '@gsm-common/hooks/usePeriodicScreenshots';
import type { ScreenshotQuality } from '@gsm-common/hooks/usePeriodicScreenshots';
import { useWakeLock } from '@gsm-common/hooks/useWakeLock';
import { createError } from '@gsm-common/utils/toast/createError';
import { createWarning } from '@gsm-common/utils/toast/createWarning';
import {
    BuildSelectionMismatchError,
    type Env,
    ErrorCode,
    GameError,
    type LogEntry,
    LogLevel,
    type PlayerMetricEvent,
    StartGameError,
    useControllerQRCode,
    useGamingClient,
    useGamingClientMonitor,
} from '@ncgt/player';
import { useSessionTimelinePanel } from '@ncgt/session-timeline';
import { useTelemetry } from '@ui-paved-road/telemetry/react';
import { type DockviewApi, DockviewReact } from 'dockview';
import { type MouseEvent, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import 'dockview/dist/styles/dockview.css';
import '@gsm-common/components/SessionRedesign/sessionRedesign.css';
import { SSICQrCode } from '@gsm-app/components/SSICQrCode';
import { SessionSummaryBanner } from '@gsm-app/components/SessionSummaryBanner/SessionSummaryBanner';
import { IconCollapsePanelDown, IconCollapsePanelUp } from '@hawkins/assets';
import { Button } from '@hawkins/components';
import { type PlayPageContextValue, PlayPageProvider, type Playhead } from './PlayPageContext';
import { Background } from './components/Background';
import { DOCK_COMPONENTS, DockTabHeader, setupDefaultLayout, setupFixedPanelWidths } from './components/DockPanels';
import { PageHeader } from './components/PageHeader';
import { PagePlayer } from './components/PagePlayer';
import { useGameChannels } from './hooks/useGameChannels';
import { useStreamingModeInfo } from './hooks/useStreamingModeInfo';

const stageByMetricName: Record<string, string> = {
    'player.stage.signaling_ms': 'signaling',
    'player.stage.webrtc_ms': 'webrtc',
    'player.stage.first_frame_ms': 'first_frame',
};

const toastInfoByGameErrorCode: Partial<Record<ErrorCode, { title: string; body: string }>> = {
    [ErrorCode.COULD_NOT_CONNECT_TO_ANY_SIGNALING_SERVER]: {
        title: 'Connection Failed',
        body: 'Could not connect to the gaming server. This may be due to network issues, firewall restrictions, or high latency. Please check your network connection and try again.',
    },
    [ErrorCode.FAILED_TO_CONNECT_TO_SIGNALING_SERVER]: {
        title: 'Connection Failed',
        body: 'Failed to connect to the signaling server. Please check your network connection and try again.',
    },
    [ErrorCode.STUN_BLOCKED]: {
        title: 'Network Blocked',
        body: 'WebRTC connections are blocked. Please check your firewall or network settings.',
    },
    [ErrorCode.STUN_BLOCKED_PORT_RANGE]: {
        title: 'Network Blocked',
        body: 'Required network ports are blocked. Please check your firewall settings.',
    },
    [ErrorCode.TIMEOUT_ESTABLISHING_CONNECTION]: {
        title: 'Connection Timeout',
        body: 'The connection timed out. This may be due to high latency or network issues.',
    },
    [ErrorCode.NO_ICE_CANDIDATES]: {
        title: 'Connection Failed',
        body: 'Could not establish a peer-to-peer connection. Please check your network settings.',
    },
};

// Telemetry context keys
const CG_GAME_ID = 'cgGameId';
const CG_BUILD_ID = 'cgBuildId';
const CG_OCGA_SHORT_NAME = 'cgOcgaShortName';
const CG_ERROR_TYPE = 'cgErrorType';
const CG_ERROR_CODE = 'cgErrorCode';
const CG_ERROR_STAGE = 'cgErrorStage';
const CG_STAGE = 'cgStage';
const CG_END_REASON = 'cgEndReason';

export const Play = () => {
    const queryParams = useMemo(() => new URLSearchParams(window.location.search), []);
    const autoConnect = useMemo(() => queryParams.has('autoConnect'), [queryParams]);
    const { headless, enableLoadCustomTestbedVersion, controllerBeacon, networkValidation } = useFeature();
    const {
        open: isSessionTimelineOpen,
        onExpand: onSessionTimelineExpand,
        onCollapse: onSessionTimelineCollapse,
    } = useSessionTimelinePanel();
    const gamingClient = useGamingClient();
    // CONNECTION INFO
    const [mode, setMode] = useState<StreamingMode>(StreamingMode.INITIAL);
    const { isDisconnected, isLoading } = useStreamingModeInfo(mode);

    // SIGNALING SERVER
    const [failedMessage, setFailedMessage] = useState<string | undefined>(undefined);
    const [failedSession, setFailedSession] = useState<boolean | undefined>(false);
    const {
        channelOptions,
        areChannelsFetching,
        areChannelsRefetching,
        setSelectedChannel,
        selectedChannel,
        refetchChannels,
        gameOptions,
        activeBuild,
        selectedGame,
        setSelectedGame,
    } = useGameChannels();

    const { savedAccounts, selectedAccount, setSelectedAccount, isLoading: sopLoading } = useSopAccounts();

    const { selectedEnvOptions, setSelectedEnvOptions } = useEnvOptions({ selectedGame });

    const { sessionSettings, setSessionSettings } = useSessionSettings();

    const [autoPlay, setAutoPlay] = useState(false);

    const telemetry = useTelemetry();
    telemetry.setLoggingTag('gdt-portal', headless ? 'Play-headless-toolkit' : 'Play');

    useWakeLock(!isDisconnected);

    // sync selected game with game client
    useEffect(() => {
        if (selectedGame) {
            gamingClient.setGameId(Number(selectedGame.value));
        }
    }, [selectedGame, gamingClient]);

    // sync selected channel and build with game client
    useEffect(() => {
        if (selectedChannel) {
            gamingClient.setChannelName(selectedChannel.label);
            gamingClient.setChannelId(selectedChannel.value);
        }
        if (activeBuild) {
            gamingClient.setBuildId(activeBuild.id);
        }
        // TODO - reset graph data
    }, [selectedChannel, activeBuild, gamingClient]);

    useEffect(() => {
        if (failedSession && selectedGame) {
            setFailedMessage(
                `Cannot play game (Are you sure you uploaded a game for this branch (GameId: ${selectedGame.value}, Name: ${selectedGame.label}))`,
            );
        } else {
            setFailedMessage(undefined);
        }
    }, [failedSession, selectedGame]);

    const [sessionId, setSessionId] = useState<string>();

    // Approximate t=0 reference for the shared playhead below — captured once per session so
    // displayed durations ("00:23") stay small/sane on both the graph and the logs panel. Sync
    // correctness between the two Dockview panels doesn't depend on this being exact.
    const [sessionStartMs, setSessionStartMs] = useState(0);
    useEffect(() => {
        if (sessionId) setSessionStartMs(Date.now());
    }, [sessionId]);

    // Shared playhead between the perf graph (Dockview "perf" panel) and the logs panel
    // (Dockview "logs" panel) — connected only via PlayPageContext since they're separate panels.
    const [playhead, setPlayhead] = useState<Playhead>(null);
    const onGraphPlayhead = useCallback((time: number) => {
        setPlayhead({ time, source: 'graph' });
    }, []);
    const onLogPlayhead = useCallback((time: number) => {
        setPlayhead({ time, source: 'log' });
    }, []);

    // Lifted here (rather than fetched separately in the logs panel and the perf graph panel)
    // so both dockview panels share a single telemetry subscription for each log stream.
    const gameLogs = useSessionGameLogs({
        sessionId,
        live: true,
        disabled: !sessionId || (mode !== StreamingMode.OPEN && mode !== StreamingMode.CLOSED),
    });
    const controllerLogs = useControllerLogs({
        sessionId,
        disabled: !sessionId || (mode !== StreamingMode.OPEN && mode !== StreamingMode.CLOSED),
    });

    const clientId = useUniqueClientId(); // Unique ESN associated with this client
    const {
        data: passportData,
        error: passportError,
        isError: isPassportError,
    } = usePassport(selectedAccount?.value, clientId);
    const {
        data: controllerQRCode,
        error,
        isError,
    } = useControllerQRCode({
        disabled: isDisconnected,
        gameId: selectedGame?.value,
        sessionId,
        cloudGameToken: gamingClient.getBeaconToken(),
        passport: passportData?.data,
    });

    useEffect(() => {
        if (isError && error) {
            console.error(error);
            telemetry.trackError(error);

            createError({
                title: 'Error generating QR Code',
                body: `${error.message}`,
                options: {
                    duration: 3500,
                    id: 'controller-qr-code-error',
                },
            });
        }
    }, [error, isError, telemetry]);

    useEffect(() => {
        if (isPassportError && passportError) {
            telemetry.trackError(passportError);
        }
    }, [isPassportError, passportError, telemetry]);

    const [ssicWindowConfig, setSsicWindowConfig] = useState<SsicWindowConfig>({ minSSIC: 1, maxSSIC: 4 });

    const { controllerOptions, sideloadedControllerUrl, selectedController, setSelectedController } =
        useGameControllers(selectedGame?.value, activeBuild?.key);

    const { showSSIC, setShowSSIC, controllerEnv, setControllerEnv, testbedVersion, setTestbedVersion } = useSsicWindow(
        {
            qrCodeUrl: controllerQRCode?.qrCodeUrl,
            config: ssicWindowConfig,
            passport: passportData?.data,
        },
    );

    const handleSetSelectedController = useCallback(
        (controllerId: string | undefined) => {
            const option = controllerOptions.find((option) => option.value === controllerId);

            if (option) {
                gamingClient.setQrCodeConfig(option.config);
                setSelectedController(option.value);
            }
        },
        [controllerOptions, gamingClient.setQrCodeConfig, setSelectedController],
    );

    const firstMount = useRef<boolean>(true);
    const successCountedSessionIdRef = useRef<string | undefined>(undefined);
    const sessionStartedAtMsRef = useRef<number | undefined>(undefined);
    const sessionEndedSessionIdRef = useRef<string | undefined>(undefined);
    const sessionContextRef = useRef<{ gameId: number; buildId: string; ocgaShortName?: string } | undefined>(
        undefined,
    );

    const gameEnvs = useMemo<Env[]>(() => {
        const envs: Env[] = selectedEnvOptions
            .filter((option) => option.enabled !== false)
            .map((option) => ({
                key: option.key,
                value: option.value,
            }));
        if (autoPlay) {
            envs.push({ key: 'NFLX_AUTOPLAY_MODE', value: 'TRUE' });
        }
        return envs;
    }, [selectedEnvOptions, autoPlay]);

    const ocgas = useMemo(
        () => (sessionSettings.ocgaSteeringOverride ? [sessionSettings.ocgaSteeringOverride] : undefined),
        [sessionSettings.ocgaSteeringOverride],
    );

    const ocgaOverrides = useMemo(
        () => ({
            gameEnvs,
            ocgas,
            hardwareVersionSelection: sessionSettings.hardwareVersionSelection,
            softwareGameDevPool: sessionSettings.softwareGameDevPool,
            resolutionOverride: sessionSettings.resolutionOverride,
            fpsOverride: sessionSettings.fpsOverride,
        }),
        [
            gameEnvs,
            ocgas,
            sessionSettings.hardwareVersionSelection,
            sessionSettings.softwareGameDevPool,
            sessionSettings.resolutionOverride,
            sessionSettings.fpsOverride,
        ],
    );

    const setTelemetryGameAndBuildContext = useCallback(
        (gameId: number | undefined, buildId: string | undefined) => {
            telemetry.setContext(CG_GAME_ID, gameId ? String(gameId) : null);
            telemetry.setContext(CG_BUILD_ID, buildId ?? null);
        },
        [telemetry],
    );

    const setTelemetryErrorContext = useCallback(
        (error: unknown) => {
            const getErrorType = (e: unknown) => {
                switch (true) {
                    case e instanceof GameError:
                        return 'game_error';
                    case e instanceof StartGameError:
                        return 'start_game_error';
                    case e instanceof BuildSelectionMismatchError:
                        return 'build_selection_mismatch';
                    default:
                        return 'unknown';
                }
            };

            const errorType = getErrorType(error);

            telemetry.setContext(CG_ERROR_TYPE, errorType);

            // Clear stale error context from any previous session/error
            telemetry.setContext(CG_ERROR_CODE, null);
            telemetry.setContext(CG_ERROR_STAGE, 'unknown');
            telemetry.setContext(CG_OCGA_SHORT_NAME, null);

            if (error instanceof GameError) {
                telemetry.setContext(CG_ERROR_CODE, String(error.code));
                telemetry.setContext(CG_ERROR_STAGE, error.diagnostics?.stage ?? 'unknown');
                telemetry.setContext(CG_OCGA_SHORT_NAME, error.diagnostics?.ocgaShortName ?? null);
            }
        },
        [telemetry],
    );

    const trackPlayerStreamFailure = useCallback(
        (error: unknown) => {
            telemetry.trackCount('player.stream_failure', 1);
            telemetry.trackError(error);
        },
        [telemetry],
    );

    const forwardPlayerLogToTelemetry = useCallback(
        (logEntry: LogEntry) => {
            const logMessage = `[Player/${logEntry.topic}] ${logEntry.message}`;
            if (logEntry.level >= LogLevel.ERROR) {
                telemetry.logger.error(logMessage);
            } else if (logEntry.level >= LogLevel.WARN) {
                telemetry.logger.warn(logMessage);
            } else if (logEntry.level >= LogLevel.INFO) {
                telemetry.logger.info(logMessage);
            } else {
                telemetry.logger.debug(logMessage);
            }
        },
        [telemetry],
    );

    const trackPlayerMetric = useCallback(
        (metric: PlayerMetricEvent) => {
            telemetry.setContext(CG_GAME_ID, String(metric.metadata.gameId));
            telemetry.setContext(CG_BUILD_ID, metric.metadata.buildId || null);
            telemetry.setContext(CG_OCGA_SHORT_NAME, metric.metadata.ocgaShortName ?? null);

            const stage = stageByMetricName[metric.name] ?? null;
            if (stage) {
                telemetry.setContext(CG_STAGE, stage);
                telemetry.trackDuration('player.stage_duration_ms', metric.valueMs);
            } else {
                telemetry.setContext(CG_STAGE, null);
                telemetry.trackDuration(metric.name, metric.valueMs);
            }
        },
        [telemetry],
    );

    const trackPlayerStreamSuccessOncePerSession = useCallback(
        (metric: PlayerMetricEvent) => {
            if (metric.name !== 'player.ttff_ms') {
                return;
            }

            const sessionId = gamingClient.getGamePlaySessionId();
            if (successCountedSessionIdRef.current === sessionId) {
                return;
            }

            successCountedSessionIdRef.current = sessionId;
            sessionStartedAtMsRef.current = Date.now();
            sessionEndedSessionIdRef.current = undefined;
            sessionContextRef.current = metric.metadata;
            telemetry.trackCount('player.stream_success', 1);
        },
        [gamingClient, telemetry],
    );

    const processTestbedVersion = () => {
        const version = testbedVersion.trim();

        if (!enableLoadCustomTestbedVersion || version === '' || version === TESTBED_VERSION_LATEST) {
            return undefined;
        }

        return version;
    };

    const { loadingProgress } = useGamingClientMonitor(mode === StreamingMode.CONNECTING && !sopLoading, gamingClient, {
        sopAccountEmail: selectedAccount?.value ?? '',
        sopAccountPin: selectedAccount?.pin ?? '',
        buildId: activeBuild?.id ?? '',
        controllerEnv,
        testbedVersion: processTestbedVersion(),
        ocgaOverrides,
        onError: (e) => {
            console.error(e);

            const gameId = selectedGame?.value ? Number(selectedGame.value) : undefined;
            const buildId = activeBuild?.id;

            setTelemetryGameAndBuildContext(gameId, buildId);
            setTelemetryErrorContext(e);
            trackPlayerStreamFailure(e);

            if (e instanceof BuildSelectionMismatchError) {
                createWarning({
                    title: e.title,
                    body: e.message || undefined,
                    options: {
                        id: 'build-selection-mismatch-error',
                    },
                });
                return;
            }

            if (e instanceof StartGameError) {
                createError({
                    title: e.title,
                    body: e.message || undefined,
                    options: {
                        id: 'start-game-error',
                    },
                });
            } else if (e instanceof GameError) {
                const errorInfo = toastInfoByGameErrorCode[e.code] || {
                    title: 'Game Error',
                    body: e.message || `An error occurred (code: ${e.code})`,
                };

                createError({
                    title: errorInfo.title,
                    body: errorInfo.body,
                    options: {
                        id: `game-error-${e.code}`,
                    },
                });
            }
            disconnect('error');
        },
        onLog: forwardPlayerLogToTelemetry,
        onMetric: (metric: PlayerMetricEvent) => {
            trackPlayerMetric(metric);
            trackPlayerStreamSuccessOncePerSession(metric);
        },
        logForwardingOptions: {
            minLevel: LogLevel.DEBUG,
        },
    });

    useEffect(() => {
        let currentSessionId: string;

        const handleSessionCreate = () => {
            const sessionId = gamingClient.getGamePlaySessionId();
            setSessionId(sessionId);
        };

        const handlePlaying = () => {
            const sessionId = gamingClient.getGamePlaySessionId();
            if (currentSessionId === sessionId) {
                return;
            }
            currentSessionId = sessionId;

            setSessionId(sessionId);
            setMode(StreamingMode.OPEN);
            setPerformanceSummary(null); // clear previous session summary

            if (headless) {
                try {
                    const ocgaURL = gamingClient.getGamingAppliance()?.hostInfo?.url;
                    const beaconToken = gamingClient.getBeaconToken();
                    const gamingStartToken = gamingClient.getGamingStartToken();
                    const sessionDetails = { sessionId, ocgaURL, gamingStartToken, beaconToken };
                    // @ts-ignore
                    globalThis.window.AppAPI.setSessionDetails(sessionDetails);
                } catch (error) {
                    console.error(error);
                    telemetry.trackError(error);
                }
            }
        };

        const handleAutoPlayBlocked = () => setMode(StreamingMode.AUTOPLAY_BLOCKED);

        // TODO - figure out why connection errors were not being used
        // const handleConnectionError = (e: { type: 'gamecontrolconnectionerror'; message: string }) => {
        //     telemetry.logger.error(`${e.name}: ${e.message}`);

        //     setFailedSession(true);
        //     disconnect();
        // };

        const handleBeforeUnload = () => {
            disconnect('unload');
        };

        gamingClient.addEventListener('sessionCreate', handleSessionCreate);
        gamingClient.addEventListener('playing', handlePlaying);
        gamingClient.addEventListener('autoplayblocked', handleAutoPlayBlocked);
        // gamingClient.addEventListener('gamecontrolconnectionerror', handleConnectionError);
        window.addEventListener('beforeunload', handleBeforeUnload);

        if (firstMount.current) {
            window.netflix = window.netflix ?? {};
            window.netflix.gamingClient = gamingClient;

            firstMount.current = false;
            if (autoConnect) {
                start();
            }
        } else if (autoConnect && mode === StreamingMode.INITIAL) {
            start();
        }

        // cleanup listeners
        return () => {
            gamingClient.removeEventListener('sessionCreate', handleSessionCreate);
            gamingClient.removeEventListener('playing', handlePlaying);
            gamingClient.removeEventListener('autoplayblocked', handleAutoPlayBlocked);
            // gamingClient.removeEventListener('gamecontrolconnectionerror', handleConnectionError);
            window.removeEventListener('beforeunload', handleBeforeUnload);
        };
    }, [gamingClient, headless, mode, autoConnect, telemetry]);

    const start = useCallback(() => {
        telemetry.trackFeatureEngagement('Play Game', 'start', {
            account: selectedAccount?.value,
            game: Number(selectedGame?.value),
            channel: selectedChannel?.label,
        });

        // Track OCGA overrides when applied at game start
        if (sessionSettings.ocgaSteeringOverride) {
            telemetry.trackFeatureEngagement('OCGA Steering Override Applied', 'uuid_override', {
                gameId: Number(selectedGame?.value),
                ocgaUUID: sessionSettings.ocgaSteeringOverride,
            });
        } else if (sessionSettings.hardwareVersionSelection) {
            const [hardwareType, environment] = sessionSettings.hardwareVersionSelection.split(':');
            telemetry.trackFeatureEngagement('OCGA Steering Override Applied', 'hardware_override', {
                gameId: Number(selectedGame?.value),
                hardwareType,
                environment,
            });
        } else if (sessionSettings.softwareGameDevPool) {
            telemetry.trackFeatureEngagement('OCGA Steering Override Applied', 'software_pool_override', {
                gameId: Number(selectedGame?.value),
                softwareGameDevPool: sessionSettings.softwareGameDevPool,
            });
        }

        setFailedSession(false);
        setMode(StreamingMode.CONNECTING);
    }, [selectedAccount, selectedGame, selectedChannel, sessionSettings, telemetry]);

    const disconnect = useCallback(
        (reason: 'user_stop' | 'error' | 'unload' | 'unmount' | 'unknown' = 'unknown') => {
            // If the stream reached first frame, track session end + duration once per session.
            const startedSessionId = successCountedSessionIdRef.current;
            const startedAtMs = sessionStartedAtMsRef.current;
            const ctx = sessionContextRef.current;

            if (!startedSessionId || !startedAtMs || sessionEndedSessionIdRef.current === startedSessionId) {
                gamingClient.close();
                setMode(StreamingMode.CLOSED);
                setShowSSIC(false);
                return;
            }

            sessionEndedSessionIdRef.current = startedSessionId;
            telemetry.setContext(CG_END_REASON, reason);

            if (ctx) {
                telemetry.setContext(CG_GAME_ID, String(ctx.gameId));
                telemetry.setContext(CG_BUILD_ID, ctx.buildId || null);
                telemetry.setContext(CG_OCGA_SHORT_NAME, ctx.ocgaShortName ?? null);
            }

            telemetry.trackCount('player.session_end', 1);
            telemetry.trackDuration('player.session_duration_ms', Date.now() - startedAtMs);

            gamingClient.close();
            setMode(StreamingMode.CLOSED);
            setShowSSIC(false);
        },
        [gamingClient, setShowSSIC, telemetry],
    );

    // cleanup function - closes gamingClient on play unmount
    useEffect(() => {
        return () => {
            disconnect('unmount');
        };
    }, [disconnect]);

    const toggleConnection = useCallback(
        (event: MouseEvent<HTMLButtonElement>): void => {
            (event.target as HTMLButtonElement).blur();
            (async () => {
                // Refetch the channels to ensure the most recent build is used
                if (isDisconnected) {
                    try {
                        await refetchChannels();
                    } catch (error) {
                        console.error(error);
                        telemetry.trackError(error);
                    } finally {
                        start();
                    }
                } else {
                    disconnect('user_stop');
                }
            })();
        },
        [start, disconnect, isDisconnected, refetchChannels, telemetry],
    );

    // start game for headless mode
    useEffect(() => {
        if (headless && selectedChannel && selectedGame) {
            start();
        }
    }, [start, headless, selectedChannel, selectedGame]);

    const [viewMode, setViewMode] = useState<'developer' | 'grid'>('developer');
    const [isQrCollapsed, setIsQrCollapsed] = useState(false);
    const [showSettingsPanel, setShowSettingsPanel] = useState(false);
    const [showGraphsNetwork, setShowGraphsNetwork] = useState(true);
    const [showLogsPanel, setShowLogsPanel] = useState(true);
    const [showQrPanel, setShowQrPanel] = useState(true);
    const [showOverviewPanel, setShowOverviewPanel] = useState(false);
    const [popoutPanels, setPopoutPanels] = useState<Set<string>>(new Set());
    const [dockKey] = useState(0);

    const dockApiRef = useRef<DockviewApi | null>(null);
    const removePanelListenerRef = useRef<{ dispose: () => void } | null>(null);
    // Tracks panels mid-popout so onDidRemovePanel doesn't treat them as hard-closed
    const poppingOutRef = useRef<Set<string>>(new Set());

    useEffect(() => {
        return () => {
            removePanelListenerRef.current?.dispose();
        };
    }, []);

    const [enableScreenshots, setEnableScreenshots] = useState(true);
    const [captureIntervalMs, setCaptureIntervalMs] = useState(DEFAULT_CAPTURE_INTERVAL_MS);
    const [screenshotQuality, setScreenshotQuality] = useState<ScreenshotQuality>(DEFAULT_SCREENSHOT_QUALITY);
    const [enforceEnvelope, setEnforceEnvelope] = useState(true);
    const [resourceDisplayMode, setResourceDisplayMode] = useState<'percent' | 'both'>('percent');
    const [resourceLimits, setResourceLimits] = useState({ cpu: 100, gpu: 100, ram: 8192, vram: 8192 });
    const [performanceSummary, setPerformanceSummary] = useState<PerformanceSummary | null>(null);
    const screenshots = usePeriodicScreenshots(mode, enableScreenshots, captureIntervalMs, screenshotQuality);

    const playPageContext: PlayPageContextValue = {
        sessionId,
        mode,
        activeBuild,
        isLoading,
        isDisconnected,
        failedMessage,
        loadingProgress,
        toggleConnection,
        selectedGame,
        selectedChannel,
        qrCodeUrl: controllerQRCode?.qrCodeUrl,
        passport: passportData?.data,
        showSSIC,
        setShowSSIC,
        controllerEnv,
        setControllerEnv,
        ssicWindowConfig,
        setSsicWindowConfig,
        sideloadedControllerUrl,
        controllerOptions,
        selectedController,
        setSelectedController: handleSetSelectedController,
        testbedVersion,
        setTestbedVersion,
        selectedEnvOptions,
        setSessionSettings,
        setSelectedEnvOptions,
        screenshots,
        enableScreenshots,
        captureIntervalMs,
        screenshotQuality,
        onEnableScreenshotsChange: setEnableScreenshots,
        onCaptureIntervalChange: setCaptureIntervalMs,
        onScreenshotQualityChange: setScreenshotQuality,
        enforceEnvelope,
        onEnforceEnvelopeChange: setEnforceEnvelope,
        resourceDisplayMode,
        onResourceDisplayModeChange: setResourceDisplayMode,
        resourceLimits,
        onResourceLimitsChange: setResourceLimits,
        performanceSummary,
        setPerformanceSummary,
        gameLogs,
        controllerLogs,
        playhead,
        onGraphPlayhead,
        onLogPlayhead,
        sessionStartMs,
    };

    const handlePanelPopout = useCallback((panelId: string, isPopped: boolean) => {
        if (isPopped) {
            poppingOutRef.current.add(panelId);
        } else {
            poppingOutRef.current.delete(panelId);
        }
        setPopoutPanels((prev) => {
            const next = new Set(prev);
            isPopped ? next.add(panelId) : next.delete(panelId);
            return next;
        });
    }, []);

    const handleGraphsNetworkToggle = useCallback(() => {
        const api = dockApiRef.current;
        if (!api) return;
        const perfPanel = api.getPanel('perf');
        if (perfPanel) {
            const nextVisible = !showGraphsNetwork;
            perfPanel.group.api.setVisible(nextVisible);
            setShowGraphsNetwork(nextVisible);
        } else {
            api.addPanel({
                id: 'perf',
                component: 'perf',
                title: 'Performance',
                position: { direction: 'left', referencePanel: 'player' },
                initialWidth: 550,
            });
            if (networkValidation) {
                api.addPanel({
                    id: 'network',
                    component: 'network',
                    title: 'Network Activity',
                    position: { direction: 'within', referencePanel: 'perf' },
                    inactive: true,
                });
                api.getPanel('perf')?.api.setActive();
            }
            setShowGraphsNetwork(true);
        }
    }, [networkValidation, showGraphsNetwork]);

    const handleLogsToggle = useCallback(() => {
        const api = dockApiRef.current;
        if (!api) return;
        const panel = api.getPanel('logs');
        if (panel) {
            const nextVisible = !showLogsPanel;
            panel.group.api.setVisible(nextVisible);
            setShowLogsPanel(nextVisible);
        } else {
            const logsPanel = api.addPanel({
                id: 'logs',
                component: 'logs',
                title: 'Logs',
                position: { direction: 'below', referencePanel: 'player' },
            });
            logsPanel.group.element.classList.add('logs-group');
            setShowLogsPanel(true);
        }
    }, [showLogsPanel]);

    const handleQrToggle = useCallback(() => {
        const api = dockApiRef.current;
        if (!api) return;
        const panel = api.getPanel('qr');
        if (panel) {
            const nextVisible = !showQrPanel;
            panel.group.api.setVisible(nextVisible);
            setShowQrPanel(nextVisible);
        } else {
            const qrPanel = api.addPanel({
                id: 'qr',
                component: 'qr',
                title: 'NGC QR Code',
                position: api.getPanel('logs')
                    ? { direction: 'left', referencePanel: 'logs' }
                    : { direction: 'below', referencePanel: 'player' },
                initialWidth: 230,
            });
            qrPanel.group.element.classList.add('logs-group');
            setShowQrPanel(true);
        }
    }, [showQrPanel]);

    const handleOverviewToggle = useCallback(() => {
        const api = dockApiRef.current;
        if (!api) return;
        const panel = api.getPanel('overview');
        if (panel) {
            const nextVisible = !showOverviewPanel;
            panel.group.api.setVisible(nextVisible);
            setShowOverviewPanel(nextVisible);
        } else {
            api.addPanel({
                id: 'overview',
                component: 'overview',
                title: 'Session Overview',
                position: { direction: 'right', referencePanel: 'player' },
                initialWidth: 280,
            });
            setShowOverviewPanel(true);
        }
    }, [showOverviewPanel]);

    const handleAllPanelsToggle = useCallback(() => {
        const allOpen = showGraphsNetwork && showLogsPanel && showQrPanel && showOverviewPanel;
        if (allOpen) {
            handleGraphsNetworkToggle();
            handleLogsToggle();
            handleQrToggle();
            handleOverviewToggle();
        } else {
            if (!showLogsPanel) handleLogsToggle();
            if (!showQrPanel) handleQrToggle();
            if (!showGraphsNetwork) handleGraphsNetworkToggle();
            if (!showOverviewPanel) handleOverviewToggle();
        }
    }, [
        showGraphsNetwork,
        showLogsPanel,
        showQrPanel,
        showOverviewPanel,
        handleGraphsNetworkToggle,
        handleLogsToggle,
        handleQrToggle,
        handleOverviewToggle,
    ]);

    const handleViewModeChange = useCallback((mode: 'developer' | 'grid') => {
        setViewMode(mode);
        const api = dockApiRef.current;
        if (!api) return;
        if (mode === 'grid') {
            const playerPanel = api.getPanel('player');
            if (playerPanel) api.maximizeGroup(playerPanel);
        } else {
            if (api.hasMaximizedGroup()) api.exitMaximizedGroup();
        }
    }, []);

    const handleSettingsToggle = useCallback(() => {
        const api = dockApiRef.current;
        if (!api) return;
        const panel = api.getPanel('settings');
        if (panel) {
            panel.api.close();
            setShowSettingsPanel(false);
        } else {
            api.addPanel({
                id: 'settings',
                component: 'settings',
                title: 'Settings',
                position: { direction: 'right' },
                initialWidth: 350,
            });
            setShowSettingsPanel(true);
        }
    }, []);

    // return PagePlayer for headless mode
    if (headless) {
        return (
            <div style={{ width: '100vw', height: '100vh', overflow: 'hidden' }}>
                <Content layout={{ padding: 0 }} style={{ width: '100%', height: '100%' }}>
                    <div
                        id='video-container'
                        style={{
                            width: '100%',
                            height: '100%',
                            display: 'flex',
                            justifyContent: 'center',
                            alignItems: 'center',
                        }}
                    >
                        <PagePlayer
                            loading={isLoading}
                            mode={mode}
                            failedMessage={failedMessage}
                            disabled={true}
                            fullWindow={true}
                            loadingProgress={loadingProgress}
                        />
                    </div>
                </Content>
            </div>
        );
    }

    return (
        <Content layout={{ padding: 0 }}>
            <Background />
            <Layout horizontal>
                <Layout full>
                    <div style={{ position: 'relative', display: 'flex', flexDirection: 'column', height: '100%' }}>
                        <PageHeader
                            mode={mode}
                            build={activeBuild}
                            sessionId={sessionId}
                            setSelectedGameOption={setSelectedGame}
                            selectedGameOption={selectedGame}
                            gameOptions={gameOptions}
                            setSelectedChannelOption={setSelectedChannel}
                            selectedChannelOption={selectedChannel}
                            areChannelsFetching={areChannelsFetching}
                            areChannelsRefetching={areChannelsRefetching}
                            channelOptions={channelOptions}
                            selectedEnvOptions={selectedEnvOptions}
                            setSelectedEnvOptions={setSelectedEnvOptions}
                            sessionSettings={sessionSettings}
                            setSessionSettings={setSessionSettings}
                            savedAccounts={savedAccounts}
                            selectedAccount={selectedAccount}
                            setSelectedAccount={setSelectedAccount}
                            onToggleConnection={toggleConnection}
                            viewMode={viewMode}
                            onViewModeChange={handleViewModeChange}
                            onSettingsClick={handleSettingsToggle}
                            isSettingsPanelOpen={showSettingsPanel}
                            showGraphsNetwork={showGraphsNetwork}
                            onGraphsNetworkToggle={handleGraphsNetworkToggle}
                            showLogsPanel={showLogsPanel}
                            onLogsToggle={handleLogsToggle}
                            showQrPanel={showQrPanel}
                            onQrToggle={handleQrToggle}
                            showOverviewPanel={showOverviewPanel}
                            onOverviewToggle={handleOverviewToggle}
                            onAllPanelsToggle={handleAllPanelsToggle}
                            isPerfPopout={popoutPanels.has('perf')}
                            isLogsPopout={popoutPanels.has('logs')}
                            isQrPopout={popoutPanels.has('qr')}
                            isOverviewPopout={popoutPanels.has('overview')}
                            autoPlay={autoPlay}
                            onAutoPlayChange={setAutoPlay}
                        />
                        <PlayPageProvider value={playPageContext}>
                            {performanceSummary && (
                                <SessionSummaryBanner
                                    summary={performanceSummary}
                                    onDismiss={() => setPerformanceSummary(null)}
                                />
                            )}
                            <div className='sr-dock-container dockview-theme-abyss'>
                                <DockviewReact
                                    key={dockKey}
                                    components={DOCK_COMPONENTS}
                                    defaultTabComponent={DockTabHeader}
                                    onReady={(event) => {
                                        dockApiRef.current = event.api;
                                        setupDefaultLayout(event.api);
                                        setupFixedPanelWidths(event.api);
                                        event.api.getPanel('overview')?.group.api.setVisible(false);
                                        if (networkValidation) {
                                            event.api.addPanel({
                                                id: 'network',
                                                component: 'network',
                                                title: 'Network Activity',
                                                position: { direction: 'within', referencePanel: 'perf' },
                                                inactive: true,
                                            });
                                            event.api.getPanel('perf')?.api.setActive();
                                        }
                                        removePanelListenerRef.current = event.api.onDidRemovePanel((panel) => {
                                            // Skip panels being moved to a popout window
                                            if (poppingOutRef.current.has(panel.id)) return;
                                            if (panel.id === 'perf') setShowGraphsNetwork(false);
                                            if (panel.id === 'settings') setShowSettingsPanel(false);
                                            if (panel.id === 'logs') setShowLogsPanel(false);
                                            if (panel.id === 'qr') setShowQrPanel(false);
                                            if (panel.id === 'overview') setShowOverviewPanel(false);
                                        });

                                        // Sync dropdown state when X button hides a panel
                                        (['perf', 'logs', 'qr'] as const).forEach((panelId) => {
                                            const panel = event.api.getPanel(panelId);
                                            if (!panel) return;
                                            panel.group.api.onDidVisibilityChange(({ isVisible }) => {
                                                if (poppingOutRef.current.has(panelId)) return;
                                                if (panelId === 'perf') setShowGraphsNetwork(isVisible);
                                                if (panelId === 'logs') setShowLogsPanel(isVisible);
                                                if (panelId === 'qr') setShowQrPanel(isVisible);
                                            });
                                        });

                                        // Pass the popout tracking callback to each panel via params
                                        (['perf', 'logs', 'qr', 'overview'] as const).forEach((panelId) => {
                                            event.api.getPanel(panelId)?.api.updateParameters({
                                                onPopout: handlePanelPopout,
                                            });
                                        });
                                    }}
                                />
                            </div>
                        </PlayPageProvider>

                        {/* QR code overlay — floats over game view in grid mode */}
                        {viewMode === 'grid' && (
                            <div className='sr-qr-overlay'>
                                {isQrCollapsed ? (
                                    <div className='sr-toolbar'>
                                        <Button
                                            compact
                                            variant='icon'
                                            icon={IconCollapsePanelUp}
                                            aria-label='Expand panel'
                                            onClick={() => setIsQrCollapsed(false)}
                                        />
                                        <span>NGC QR Code</span>
                                    </div>
                                ) : (
                                    <SSICQrCode
                                        mode={mode}
                                        qrCodeUrl={controllerQRCode?.qrCodeUrl}
                                        passport={passportData?.data}
                                        showSSIC={showSSIC}
                                        setShowSSIC={setShowSSIC}
                                        controllerEnv={controllerEnv}
                                        setControllerEnv={setControllerEnv}
                                        ssicWindowConfig={ssicWindowConfig}
                                        sideloadedControllerUrl={sideloadedControllerUrl}
                                        setSsicWindowConfig={setSsicWindowConfig}
                                        controllerOptions={controllerOptions}
                                        selectedController={selectedController}
                                        setSelectedController={handleSetSelectedController}
                                        testbedVersion={testbedVersion}
                                        setTestbedVersion={setTestbedVersion}
                                        onCollapse={() => setIsQrCollapsed(true)}
                                        collapseIcon={IconCollapsePanelDown}
                                    />
                                )}
                            </div>
                        )}
                    </div>
                </Layout>
            </Layout>
        </Content>
    );
};
