import { generatePerformanceSummary } from '@gsm-app/components/SessionSummaryBanner/generatePerformanceSummary';
import { SessionTimelineChart } from '@gsm-app/components/SessionTimelineChart/SessionTimelineChart';
import { useAppQueryParams } from '@gsm-app/hooks/useAppQueryParams';
import { useFeature } from '@gsm-app/hooks/useFeature';
import { useLogErrorWarningEvents } from '@gsm-app/hooks/useLogErrorWarningEvents';
import { useSessionTimelineMetrics } from '@gsm-app/hooks/useSessionTimelineMetrics';
import { isOcga2026Session, isVirtualOcgaSession } from '@gsm-app/models/Channel';
import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { fetch as authedFetch } from '@gsm-app/utils/fetch';
import type { Screenshot } from '@gsm-common/hooks/usePeriodicScreenshots';
import { ContextualBanner } from '@hawkins/components';
import { SessionTimelineDataProvider } from '@ncgt/session-timeline';
import { ChartProvider } from '@ncgt/session-timeline/src/providers/ChartProvider';
import { ChartType } from '@ncgt/session-timeline/src/types';
import { useEffect, useRef, useState } from 'react';
import { usePlayPage } from '../../PlayPageContext';
import { useStreamingModeInfo } from '../../hooks/useStreamingModeInfo';

// Transient server error during session startup — session record exists but OCGA
// hasn't populated StartTime yet. Show a waiting state instead of a hard error.
const isStartupRaceError = (error: string | null) => error?.includes('No session or missing StartTime') ?? false;

interface SessionPerfPanelProps {
    sessionId: string | undefined;
    mode: StreamingMode;
    screenshots?: Screenshot[];
    enforceEnvelope?: boolean;
    onEnforceEnvelopeChange?: (v: boolean) => void;
    /** Raw game/controller log lines — shared from PlayPageContext — used to derive the
     * Error & Warnings markers row shown under the screenshots row. */
    gameLogsData?: string[][];
    controllerLogsData?: string[][];
    /** Shared playhead (from PlayPageContext) — bidirectional click-sync with the logs panel. */
    currentTime?: number | null;
    sessionStartMs?: number;
    playheadSource?: 'graph' | 'log' | null;
    onGraphPlayhead?: (seconds: number) => void;
}

export const SessionPerfPanel = ({
    sessionId,
    mode,
    screenshots = [],
    enforceEnvelope = true,
    onEnforceEnvelopeChange,
    gameLogsData,
    controllerLogsData,
    currentTime,
    sessionStartMs,
    playheadSource,
    onGraphPlayhead,
}: SessionPerfPanelProps) => {
    const errorWarningEvents = useLogErrorWarningEvents(gameLogsData, controllerLogsData);
    const { isDisconnected, isLoading } = useStreamingModeInfo(mode);
    const { gameId } = useAppQueryParams();
    const { resourceEnvelope } = useFeature(gameId);
    const { setPerformanceSummary } = usePlayPage();

    // Fetch ocgaHardwareRevision once the session is playing (mode OPEN).
    // sessionId is set on sessionCreate (before the game is on hardware), so we wait
    // for mode=OPEN to ensure OCGA has populated the session context.
    const [ocgaHardwareRevision, setOcgaHardwareRevision] = useState<string | undefined>();
    const [machineHostname, setMachineHostname] = useState<string | undefined>();
    const [hwRevisionLoaded, setHwRevisionLoaded] = useState(false);

    useEffect(() => {
        setOcgaHardwareRevision(undefined);
        setMachineHostname(undefined);
        setHwRevisionLoaded(false);
    }, [sessionId]);

    useEffect(() => {
        if (!sessionId || mode !== StreamingMode.OPEN) return;
        const controller = new AbortController();
        authedFetch(`/api/sessions/${sessionId}/info`, { signal: controller.signal })
            .then((res) => (res.ok ? res.json() : null))
            .then((data) => {
                setOcgaHardwareRevision(data?.sessions?.[0]?.ocgaHardwareRevision);
                setMachineHostname(data?.sessions?.[0]?.machineHostname);
                setHwRevisionLoaded(true);
            })
            .catch(() => {});
        return () => {
            controller.abort();
        };
    }, [sessionId, mode]);

    const isOcga2026 = isOcga2026Session(ocgaHardwareRevision);
    const activeEnvelope = isOcga2026 ? resourceEnvelope : null;
    const awaitingHwRevision = resourceEnvelope != null && !hwRevisionLoaded && mode === StreamingMode.OPEN;
    const hidePerfGraphs = resourceEnvelope != null && hwRevisionLoaded && !isOcga2026;

    const { datasets, targetInstanceCount, error } = useSessionTimelineMetrics({
        gameId,
        sessionId,
        live: true,
        disabled: !sessionId || (mode !== StreamingMode.OPEN && mode !== StreamingMode.CLOSED),
        resourceEnvelope: activeEnvelope,
    });

    // Generate AI performance summary when the session ends
    const prevModeRef = useRef<StreamingMode>(mode);
    useEffect(() => {
        const wasOpen = prevModeRef.current === StreamingMode.OPEN;
        const isClosed = mode === StreamingMode.CLOSED;
        prevModeRef.current = mode;

        if (wasOpen && isClosed && enforceEnvelope) {
            const statsPoints: any[] = (datasets as any)?.[ChartType.STATS] ?? [];
            if (statsPoints.length > 0) {
                const summary = generatePerformanceSummary(statsPoints);
                setPerformanceSummary(summary);
            }
        }
    }, [mode, enforceEnvelope, datasets, setPerformanceSummary]);

    if (hidePerfGraphs) {
        return (
            <ContextualBanner
                text='Performance graphs are only available for sessions on OCGA 2026 hardware'
                variant='warning'
            />
        );
    }

    const showWaitingOverlay = !sessionId || awaitingHwRevision || isStartupRaceError(error);

    return (
        <SessionTimelineDataProvider
            data={{ ...datasets, screenshots } as { [key: string]: any }}
            error={isStartupRaceError(error) ? null : error}
            isDisconnected={isDisconnected}
            isLoading={isLoading}
            targetInstanceCount={targetInstanceCount}
        >
            <ChartProvider>
                {showWaitingOverlay ? (
                    <SessionTimelineChart
                        sessionId={undefined}
                        mode={StreamingMode.INITIAL}
                        hideInstanceCount={activeEnvelope != null}
                        isVirtualHardware={false}
                        enforceEnvelope={enforceEnvelope}
                        waitingMessage={sessionId ? 'Waiting for session to start…' : 'Press Play to start a session'}
                        showWaitingLoader={!!sessionId}
                    />
                ) : (
                    <SessionTimelineChart
                        sessionId={sessionId}
                        mode={mode}
                        hideInstanceCount={activeEnvelope != null}
                        isVirtualHardware={isVirtualOcgaSession(machineHostname)}
                        enforceEnvelope={enforceEnvelope}
                        errorWarningEvents={errorWarningEvents}
                        currentTime={currentTime}
                        sessionStartMs={sessionStartMs}
                        playheadSource={playheadSource}
                        onGraphPlayhead={onGraphPlayhead}
                    />
                )}
            </ChartProvider>
        </SessionTimelineDataProvider>
    );
};
