import { fetch as authedFetch } from '@gsm-app/utils/fetch';
import { IconClipboard } from '@hawkins/assets';
import { Button, Text, Tooltip } from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';
import { useEffect, useState } from 'react';
import { StreamingMode } from '../../../../models/StreamingMode';
import { usePlayPage } from '../../PlayPageContext';
import type { GameSession } from '../../../Sessions/routes/SessionView/hooks/useGameSession';
import styles from './SessionOverviewPanel.module.css';

function formatVideoQuality(videoHeight?: number, frameRate?: number): string | undefined {
    if (!videoHeight && !frameRate) return undefined;
    const res = videoHeight ? `${videoHeight}p` : '';
    const fps = frameRate ? `${frameRate}fps` : '';
    return `${res}${fps}` || undefined;
}

function CopyButton({ value }: { value: string }) {
    const [copied, setCopied] = useState(false);
    const handleCopy = () => {
        navigator.clipboard.writeText(value).then(() => {
            setCopied(true);
            setTimeout(() => setCopied(false), 1500);
        });
    };
    return (
        <Tooltip label={copied ? 'Copied!' : 'Copy to clipboard'}>
            <Button
                variant='icon'
                compact
                icon={IconClipboard}
                aria-label='Copy to clipboard'
                onClick={handleCopy}
                style={{ width: 20, height: 20, flexShrink: 0 }}
            />
        </Tooltip>
    );
}

interface RowProps {
    label: string;
    value?: string | null;
    loading?: boolean;
    copyable?: boolean;
    chips?: string[];
    placeholder?: string;
}

function Row({ label, value, loading, copyable, chips, placeholder = '—' }: RowProps) {
    const displayValue = chips && chips.length > 0 ? chips.join(', ') : value;
    const displayCopyable = copyable || (chips && chips.length > 0);
    return (
        <div className={styles.row}>
            <Text variant='label' colorVariant='faded' className={styles.label} component='div'>
                {label}
            </Text>
            <div className={styles.value}>
                {loading ? (
                    <Text variant='body' loading loaderProps={{ width: 120 }}>{' '}</Text>
                ) : (
                    <div style={{ display: 'flex', alignItems: 'center', gap: Dimensions.Space4, minWidth: 0 }}>
                        <Text
                            variant='body'
                            colorVariant={displayValue ? 'default' : 'faded'}
                            noWrap
                            className={styles.valueText}
                            component='div'
                        >
                            {displayValue ?? placeholder}
                        </Text>
                        {displayCopyable && displayValue && <CopyButton value={displayValue} />}
                    </div>
                )}
            </div>
        </div>
    );
}

export const SessionOverviewPanel = () => {
    const { sessionId, mode, activeBuild } = usePlayPage();

    const [sessionData, setSessionData] = useState<GameSession | undefined>();
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        setSessionData(undefined);
    }, [sessionId]);

    useEffect(() => {
        if (!sessionId || mode !== StreamingMode.OPEN) return;
        const controller = new AbortController();
        setLoading(true);
        authedFetch(`/api/sessions/${sessionId}/info`, { signal: controller.signal })
            .then((res) => (res.ok ? res.json() : null))
            .then((data: GameSession | null) => {
                if (data) setSessionData(data);
            })
            .catch(() => {})
            .finally(() => setLoading(false));
        return () => controller.abort();
    }, [sessionId, mode]);

    const isSessionOpen = mode === StreamingMode.OPEN;
    const hostnames = sessionData?.sessions?.map((s) => s.machineHostname).filter(Boolean) ?? [];
    const stackVersions = sessionData?.sessions?.map((s) => s.stackVersionBranch).filter(Boolean) ?? [];
    const videoQuality = formatVideoQuality(sessionData?.videoHeight, sessionData?.frameRate);

    return (
        <div className={styles.container}>
            <div className={styles.section}>
                <Row label='Build ID' value={activeBuild?.id} placeholder='No build selected' copyable />
                <Row label='Build Label' value={activeBuild?.label} placeholder='No build selected' copyable />
                <Row label='Session ID' value={sessionId} placeholder='Press Play to start' copyable />
            </div>

            <div className={styles.divider} />

            <div className={styles.section}>
                <Row
                    label='OCGA Environment'
                    value={sessionData?.ocgaEnv}
                    loading={isSessionOpen && loading}
                    placeholder='Available after session starts'
                />
                <Row
                    label='Client ESN'
                    value={sessionData?.esn}
                    loading={isSessionOpen && loading}
                    placeholder='Available after session starts'
                    copyable
                />
                <Row
                    label='Client Version'
                    value={sessionData?.version}
                    loading={isSessionOpen && loading}
                    placeholder='Available after session starts'
                    copyable
                />
                <Row
                    label='Device'
                    value={sessionData?.deviceName}
                    loading={isSessionOpen && loading}
                    placeholder='Available after session starts'
                />
                <Row
                    label='Video Quality'
                    value={videoQuality}
                    loading={isSessionOpen && loading}
                    placeholder='Available after session starts'
                />
                <Row
                    label='OCGA Versions'
                    chips={stackVersions}
                    loading={isSessionOpen && loading && stackVersions.length === 0}
                    placeholder='Available after session starts'
                />
                <Row
                    label='OCGA Hostnames'
                    chips={hostnames}
                    loading={isSessionOpen && loading && hostnames.length === 0}
                    placeholder='Available after session starts'
                />
            </div>
        </div>
    );
};
