import { useFeature } from '@gsm-app/hooks/useFeature';
import type { StreamingMode } from '@gsm-app/models/StreamingMode';
import { useStreamingModeInfo } from '@gsm-app/routes/Play/hooks/useStreamingModeInfo';
import { useAudioVolume } from '@gsm-common/hooks/useAudioVolume';
import {
    IconCamera,
    IconFullscreenEnter,
    IconFullscreenExit,
    IconPictureInPicture,
    IconVideoCamera,
    IconVolumeHigh,
    IconVolumeLow,
    IconVolumeMedium,
    IconVolumeOff,
} from '@hawkins/assets';
import {
    Button,
    ButtonGroup,
    HoverCard,
    type HoverCardProps,
    NotificationBadge,
    Paper,
    Slider,
} from '@hawkins/components';
import { Dimensions } from '@hawkins/variables';

import clsx from 'clsx';
import { type MouseEvent, useCallback, useMemo, useRef, useState } from 'react';

const TOOLTIP_DELAY = 500;

interface PlayerToolbarProps {
    disabled: boolean;
    fullscreen: boolean;
    mode: StreamingMode;
    fullWindow?: boolean;
    onScreenshot: (e: MouseEvent<HTMLButtonElement>) => any;
    onToggleFullscreen: (e: MouseEvent<HTMLButtonElement>) => any;
    onToggleConnection?: (e: MouseEvent<HTMLButtonElement>) => any;
    onToggleVideoCapture: (e: MouseEvent<HTMLButtonElement>) => any;
    videoCaptureState: RecordingState;
}

export const PlayerToolbar = ({
    mode,
    fullscreen,
    fullWindow = false,
    onScreenshot,
    onToggleFullscreen,
    onToggleVideoCapture,
    videoCaptureState,
}: PlayerToolbarProps) => {
    const { isPlaying } = useStreamingModeInfo(mode);
    const { headless } = useFeature();
    const videoRef = useRef<HTMLVideoElement | null>(null);
    const [isPiP, setIsPiP] = useState(false);
    const [volumeSliderOpen, setVolumeSliderOpen] = useState(false);
    const { volume, handleVolumeChange } = useAudioVolume(isPlaying);
    const preMuteVolumeRef = useRef(1);

    const onToggleMute = useCallback(() => {
        if (volume > 0) {
            preMuteVolumeRef.current = volume;
            handleVolumeChange(0);
        } else {
            handleVolumeChange(preMuteVolumeRef.current || 1);
        }
    }, [volume, handleVolumeChange]);

    const volumeIcon = useMemo(() => {
        if (volume === 0) {
            return IconVolumeOff;
        } else if (volume > 0 && volume <= 0.33) {
            return IconVolumeLow;
        } else if (volume > 0.33 && volume <= 0.66) {
            return IconVolumeMedium;
        } else {
            return IconVolumeHigh;
        }
    }, [volume]);

    const onToggle: HoverCardProps['onToggle'] = ({ open, reason }) => {
        if (reason !== 'outside-press') {
            setVolumeSliderOpen(open);
        }
    };

    const onTogglePictureInPicture = useCallback(async () => {
        videoRef.current = document.querySelector('#video_canvas > video') as HTMLVideoElement | null;

        if (!videoRef.current || !isPlaying) {
            return;
        }

        try {
            if (document.pictureInPictureElement) {
                await document.exitPictureInPicture();
                setIsPiP(false);
            } else {
                await videoRef.current.requestPictureInPicture();
                setIsPiP(true);
            }
        } catch (err) {
            console.error('PiP error:', err);
        }
    }, [isPlaying]);

    if (headless && fullscreen) {
        return null;
    }

    return (
        <div className={clsx('sr-player-toolbar', { 'sr-player-toolbar--full-window': fullWindow })}>
            <ButtonGroup justifyContent='flex-start' gap={Dimensions.Space8}>
                <HoverCard interactive placement='top-start' open={volumeSliderOpen} onToggle={onToggle}>
                    <HoverCard.Trigger>
                        <Button
                            icon={volumeIcon}
                            variant='tertiary'
                            aria-label='volume'
                            onClick={onToggleMute}
                            tooltipLabel={volume === 0 ? 'Unmute' : 'Mute'}
                            tooltipProps={{ enterDelay: TOOLTIP_DELAY }}
                        />
                    </HoverCard.Trigger>
                    <HoverCard.Content>
                        <Paper elevation={2}>
                            <Slider
                                value={Math.round(volume * 100)}
                                defaultValue={100}
                                max={100}
                                min={0}
                                maxIcon={IconVolumeHigh}
                                maxIconProps={{ 'aria-hidden': true }}
                                minIcon={IconVolumeOff}
                                minIconProps={{ 'aria-hidden': true }}
                                onChange={(_ev, newValue) => {
                                    handleVolumeChange((newValue as number) / 100);
                                }}
                                style={{ width: Dimensions.RawSize224 }}
                            />
                        </Paper>
                    </HoverCard.Content>
                </HoverCard>
            </ButtonGroup>
            <ButtonGroup justifyContent='flex-end' gap={Dimensions.Space8}>
                {!headless && (
                    <NotificationBadge invisible={!isPiP}>
                        <Button
                            icon={IconPictureInPicture}
                            variant='tertiary'
                            aria-label='picture-in-picture'
                            onClick={onTogglePictureInPicture}
                            tooltipLabel='Toggle Picture in Picture mode'
                            tooltipProps={{ enterDelay: TOOLTIP_DELAY }}
                            disabled={!isPlaying}
                        />
                    </NotificationBadge>
                )}
                <NotificationBadge invisible={videoCaptureState !== 'recording'}>
                    <Button
                        icon={IconVideoCamera}
                        variant='tertiary'
                        aria-label='video capture'
                        onClick={onToggleVideoCapture}
                        tooltipLabel={`${
                            isPlaying
                                ? videoCaptureState === 'recording'
                                    ? 'Recording Video'
                                    : 'Record Video'
                                : 'Record Disabled'
                        }`}
                        tooltipProps={{ enterDelay: TOOLTIP_DELAY }}
                        disabled={!isPlaying}
                    />
                </NotificationBadge>
                <Button
                    icon={IconCamera}
                    variant='tertiary'
                    aria-label='screenshot'
                    onClick={onScreenshot}
                    tooltipLabel={`${isPlaying ? 'Capture Screenshot' : 'Capture Disabled'}`}
                    tooltipProps={{ enterDelay: TOOLTIP_DELAY }}
                    disabled={!isPlaying}
                />
                <Button
                    icon={fullscreen ? IconFullscreenExit : IconFullscreenEnter}
                    variant='tertiary'
                    aria-label='toggle fullscreen'
                    onClick={onToggleFullscreen}
                    tooltipLabel={`${fullscreen ? 'Exit' : 'Enter'} Fullscreen`}
                    tooltipProps={{ enterDelay: TOOLTIP_DELAY }}
                />
            </ButtonGroup>
        </div>
    );
};
