import { type MutableRefObject, useLayoutEffect, useRef } from 'react';

const initLock = async (ref: MutableRefObject<WakeLockSentinel | undefined>) => {
    // wakelock initialized
    if (ref.current) {
        return;
    }

    if (navigator.wakeLock) {
        try {
            ref.current = await navigator.wakeLock.request();
        } catch (err: any) {
            console.error(`WakeLock: ${err.name}, ${err.message}`);
        }
    } else {
        console.log('WakeLock: Unsupported');
    }
};

export const useWakeLock = (enabled: boolean) => {
    const ref = useRef<WakeLockSentinel>();

    useLayoutEffect(() => {
        if (enabled) {
            initLock(ref);
        } else {
            ref.current?.release();
            ref.current = undefined;
        }
    }, [ref, enabled]);

    return {
        released: ref.current?.released ?? true,
    };
};
