import { StreamingMode } from '@gsm-app/models/StreamingMode';
import { Button, Centered, Loader, Stack, Text } from '@hawkins/components';
import { type LoadingProgress, LoadingStepLabels } from '@ncgt/player';

interface VideoLoaderProps {
    loading: boolean;
    mode: StreamingMode;
    loadingProgress?: LoadingProgress;
}

/** Get the display message based on loading progress */
const getLoadingMessage = (loadingProgress?: LoadingProgress): string => {
    if (!loadingProgress) {
        return 'Connecting...';
    }

    const { step, stepLabel, gameLoadPercent } = loadingProgress;

    // Use stepLabel if available, otherwise fall back to LoadingStepLabels
    const label = stepLabel || LoadingStepLabels[step] || 'Loading';

    // Show percentage for game loading step
    if (step === 'loading_game' && gameLoadPercent > 0) {
        return `${label}... ${gameLoadPercent}%`;
    }

    // If we're "ready" but still showing the loader, the stream is starting
    // (video events fired but video isn't visible yet)
    if (step === 'ready') {
        return 'Starting stream...';
    }

    return `${label}...`;
};

export const VideoLoader = ({ loading, mode, loadingProgress }: VideoLoaderProps) => {
    if (!loading) {
        return null;
    }

    if (mode === StreamingMode.AUTOPLAY_BLOCKED) {
        return (
            <Centered style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }}>
                <Button
                    onClick={() => {
                        (document.querySelector('#video_canvas > video') as HTMLVideoElement)?.play();
                    }}
                >
                    Play
                </Button>
            </Centered>
        );
    }

    if (mode === StreamingMode.WAITING_FOR_VOCGA) {
        return (
            <Centered style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }}>
                <Stack style={{ alignItems: 'center', display: 'flex', flexDirection: 'column' }} gap={10}>
                    <Loader style={{ color: 'white' }} />
                    <Text color='white'>Starting VOCGA...</Text>
                </Stack>
            </Centered>
        );
    }

    // Show detailed loading progress for CONNECTING mode
    return (
        <Centered style={{ position: 'absolute', top: 0, left: 0, right: 0, bottom: 0 }}>
            <Stack style={{ alignItems: 'center', display: 'flex', flexDirection: 'column' }} gap={10}>
                <Loader style={{ color: 'white' }} />
                <Text color='white'>{getLoadingMessage(loadingProgress)}</Text>
            </Stack>
        </Centered>
    );
};
